    #region enmChallanStatus
    public enum enmChallanStatus
    {
        AMOUNT_MATCHED = 1,
        AMOUNT_NOT_MATCHED = 2,
        RECORD_NOT_FOUND = 3,
        PROCESSING_FAILED = 4,
        WRONG_CAPTCHA = 5,
        SERVER_MAINTENANCE_ERROR = 6
    }
    #endregion

    public class TracesChallanVerifyRequest
    {
        public string tan { get; set; }
        public string fromDate { get; set; }          // e.g. 1-04-2026
        public string toDate { get; set; }            // e.g. 4-07-2026
        public string matchStatus { get; set; }       // CLAIMED / UNCLAIMED / ALL maybe
        public List<string> consumptionStatus { get; set; } // null if not required
    }
    public class TracesChallanVerifyResponse
    {
        public List<TracesChallanItem> data { get; set; }
        public object error { get; set; }
    }

    public class TracesChallanItem
    {
        public string bsrCode { get; set; }
        public string challanDepositDate { get; set; }
        public long challanSeqNum { get; set; }
        public decimal totalAmount { get; set; }
        public string cinNum { get; set; }
        public object consumptionDetails { get; set; }
        public int finYear { get; set; }
        public string matchStatus { get; set; }
        public long receiptNum { get; set; }

        public List<SectionTaxDetail> sectionTaxDetails { get; set; }
        public OtherDetails otherDetails { get; set; }
    }

    public class SectionTaxDetail
    {
        public string section { get; set; }
        public decimal surcharge { get; set; }
        public decimal baseTax { get; set; }
        public decimal cess { get; set; }
        public decimal total { get; set; }
        public object isSectionBreakUpExist { get; set; }
    }

    public class OtherDetails
    {
        public int? minorHead { get; set; }
        public int? majorHead { get; set; }
        public string sectionCode { get; set; }
        public string resStatus { get; set; }
    }

    #region T_ChallanStatusResult
    public struct T_ChallanStatusResult
    {
        public const string AMOUNT_MATCHED = "Amount Matched";
        public const string AMOUNT_NOT_MATCHED = "Amount Not Matched";
        public const string RECORD_NOT_FOUND = "Record Not Found";
        public const string PROCESSING_FAILED = "Processing Failed";
    }
    #endregion

    #region T_PANVerificationStatus
    public struct T_PANVerificationStatus
    {
        public const string VALID = "VALID";
        public const string VALID_OPERATIVE = "VALID AND OPERATIVE";
        public const string VALID_INOPERATIVE = "VALID AND INOPERATIVE";
        public const string INVALID = "INVALID";
        public const string ACTIVE = "ACTIVE";
