        #region RequestForAllDownloadList_New
        public TracesResponse RequestForAllDownloadList_New(out DataTable table)
        {
            table = null;

            TracesResponse objResponse = new TracesResponse();

            try
            {
                // ================================
                // STEP 1: INIT OLD DOMAIN COOKIE
                // ================================
                //makeHTTPGetRequest(
                //    "https://traces61.tdscpc.gov.in/",
                //    "https://traces.tdscpc.gov.in/"
                //);

                // ================================
                // STEP 2: SESSION BRIDGE
                // ================================
                makeHTTPGetRequest(
                    strBaseURL + "preauthV2.xhtml",
                    "https://traces.tdscpc.gov.in/"
                );

                // ================================
                // STEP 3: OPEN PAGE
                // ================================
                makeHTTPGetRequest(
                    strBaseURL + "ded/filedownload.xhtml",
                    strBaseURL + "preauthV2.xhtml"
                );

                // ================================
                // STEP 4: FETCH GRID DATA
                // ================================
                string nd = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds().ToString();
                //
                string url =
                    strBaseURL + "srv/GetReqListServlet"
                    + "?reqtype=0"
                    + "&_search=false"
                    + "&nd=" + nd
                    + "&rows=10"
                    + "&page=1"
                    + "&sidx=reqNo"
                    + "&sord=asc";

                string json = makeHTTPJsonGetRequest(url);

                if (!string.IsNullOrEmpty(json))
                {
                    table = JsonParser(json); // your existing parser
                    objResponse.Respons = enmResponse.Success;
                }
                else
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message = "Empty response";
                }
            }
            catch (WebException ex)
            {
                string err = "";

                if (ex.Response != null)
                {
                    using (StreamReader reader = new StreamReader(ex.Response.GetResponseStream()))
                    {
                        err = reader.ReadToEnd();
                    }
                }

                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = "Error: " + err;
            }
            catch (Exception ex)
            {
                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = ex.Message;
            }

            return objResponse;
        }
        #endregion

        #region callPreauth
        private string callPreauth()
        {
            string url = strBaseURL + "/preauthV2.xhtml";

            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);

            request.Method = "GET";
            request.KeepAlive = true;

            request.UserAgent = "Mozilla/5.0";
            request.Accept = "text/html,application/xhtml+xml";

            request.Headers.Add("Accept-Language", "en-US,en;q=0.9");
            request.Headers.Add("Cache-Control", "no-cache");

            request.Referer = "https://traces.tdscpc.gov.in/";

            // CRITICAL
            request.Headers.Add("Authorization", "Bearer " + tracesAuthToken);

            request.CookieContainer = objContainer;

            HttpWebResponse response = (HttpWebResponse)request.GetResponse();

            objContainer.Add(response.Cookies);

            string result = "";

            using (StreamReader reader = new StreamReader(response.GetResponseStream()))
            {
                result = reader.ReadToEnd();
            }

            return result;
        }
        #endregion

