        #region SetTracesApiToken

        private bool SetTracesApiToken(
            string strLoginJSON,
            out string strError)
        {
            strError = "";

            try
            {
                if (string.IsNullOrWhiteSpace(strLoginJSON))
                {
                    strError = "Empty login response received from TRACES.";
                    return false;
                }

                JObject objLoginJSON =
                    JObject.Parse(strLoginJSON);

                bool blnAuthenticated = false;

                if (objLoginJSON["isAuthenticated"] != null)
                {
                    bool.TryParse(
                        Convert.ToString(
                            objLoginJSON["isAuthenticated"]
                        ),
                        out blnAuthenticated
                    );
                }

                string strStatus =
                    Convert.ToString(
                        objLoginJSON["status"]
                    );

                if (!blnAuthenticated)
                {
                    strError =
                        Convert.ToString(
                            objLoginJSON["message"]
                        );

                    if (string.IsNullOrWhiteSpace(strError))
                        strError = "TRACES login failed.";

                    return false;
                }

                JObject objAuthToken =
                    objLoginJSON["authTokenDto"] as JObject;

                if (objAuthToken == null)
                {
                    strError =
                        "TRACES authorization information not received.";

                    return false;
                }

                strBearerToken =
                    Convert.ToString(
                        objAuthToken["accessToken"]
                    );

                strRefreshToken =
                    Convert.ToString(
                        objAuthToken["refreshToken"]
                    );

                if (string.IsNullOrWhiteSpace(strBearerToken))
                {
                    strError =
                        "TRACES access token not received.";

                    return false;
                }

                return true;
            }
            catch (Exception ex)
            {
                strError = ex.Message;
                return false;
            }
        }

        #endregion

        #region LoginToNewTracesApi

        private bool LoginToNewTracesApi(
            string strUserId,
            string strPassword,
            string strCaptcha,
            string strCaptchaId,
            string strUserType,
            string strSubUserPan,
            out string strError)
        {
            strError = "";

            try
            {
                string strURL =
                    "https://traces-app.tdscpc.gov.in/" +
                    "loginservice/api/auth/login";

                var objRequestData = new
                {
                    userId = strUserId,
                    userType = strUserType,
                    subUserPanId = strSubUserPan,
                    password = strPassword,
                    captcha = strCaptcha,
                    captchaId = strCaptchaId
                };

                string strJSONPayload =
                    JsonConvert.SerializeObject(
                        objRequestData
                    );

                string strLoginJSON =
                    makeHTTPPostJsonRequestWithoutToken(
                        strURL,
                        strJSONPayload,
                        "https://traces.tdscpc.gov.in/"
                    );

                if (string.IsNullOrWhiteSpace(strLoginJSON))
                {
                    strError =
                        "No response received from TRACES login service.";

                    return false;
                }

                return SetTracesApiToken(
                    strLoginJSON,
                    out strError
                );
            }
            catch (Exception ex)
            {
                strError = ex.Message;
                return false;
            }
        }

