        #region RequestForStatusofStatementFile_26_27

        public TracesResponse RequestForStatusofStatementFile_26_27(
            TracesData objData,
            out DataTable table)
        {
            table = null;

            TracesResponse objResponse =
                new TracesResponse();

            objResponse.Respons =
                enmResponse.Success;

            try
            {
                // =====================================================
                // CHECK AUTHORIZATION TOKEN
                // =====================================================

                if (string.IsNullOrWhiteSpace(
                        strBearerToken))
                {
                    objResponse.Respons =
                        enmResponse.Failed;

                    objResponse.Message =
                        "TRACES authorization token not available.";

                    return objResponse;
                }


                // =====================================================
                // PREPARE INPUT VALUES
                // =====================================================

                string strFormNumber =
                    Convert.ToString(
                        objData.Forms
                    ).Trim();

                string strFinancialYear =
                    Convert.ToString(
                        objData.FAYear
                    ).Trim();

                string strQuarter =
                    NormalizeQuarterForFiledForms(
                        Convert.ToString(
                            objData.Quarter
                        )
                    );


                // IMPORTANT:
                // Change objData.TAN below if the TAN property
                // in your TracesData class has another name.

                string strTAN =
                    Convert.ToString(
                        objData.TAN
                    ).Trim();


                // =====================================================
                // CREATE RESULT TABLE
                // =====================================================

                table = new DataTable();

                table.Columns.Add(
                    "Token Number"
                );

                // Kept same spelling as your old code
                table.Columns.Add(
                    "Finnancial Year"
                );

                table.Columns.Add(
                    "Statement Type"
                );

                table.Columns.Add(
                    "Form Type"
                );

                table.Columns.Add(
                    "Quarter"
                );

                table.Columns.Add(
                    "Date of Filling"
                );

                table.Columns.Add(
                    "Date of Processing"
                );

                table.Columns.Add(
                    "Status"
                );

                // Useful for future View Details API
                table.Columns.Add(
                    "Request Id"
                );


                // =====================================================
                // CREATE REQUEST JSON
                // =====================================================

                var objRequestData = new
                {
                    formNumber =
                        strFormNumber,

                    financialYear =
                        strFinancialYear,

                    tan =
                        strTAN,

                    quarter =
                        strQuarter
                };


                string strJSONPayload =
                    JsonConvert.SerializeObject(
                        objRequestData
                    );


                // =====================================================
                // PAGINATION
                //
                // TRACES uses:
                // page=0
                // page=1
                // page=2 ...
                // =====================================================

                int intPage = 0;
                int intTotalPages = 1;


                do
                {
                    string strURL =
                        "https://traces-app.tdscpc.gov.in/" +
                        "viewforms/search/forms?page=" +
                        intPage.ToString();


                    string json =
                        makeHTTPPostJsonRequest(
                            strURL,
                            strJSONPayload,
                            "https://traces.tdscpc.gov.in/",
                            strBearerToken
                        );


                    // =============================================
                    // CHECK EMPTY RESPONSE
                    // =============================================

                    if (string.IsNullOrWhiteSpace(json))
                    {
                        objResponse.Respons =
                            enmResponse.Failed;

                        objResponse.Message =
                            "No response received from TRACES.";

                        return objResponse;
                    }


                    // =============================================
                    // PARSE JSON
                    // =============================================

                    JObject objJSON =
                        JObject.Parse(json);


                    int intStatus = 0;

                    int.TryParse(
                        Convert.ToString(
                            objJSON["status"]
                        ),
                        out intStatus
                    );


                    string strMessage =
                        Convert.ToString(
                            objJSON["message"]
                        );


                    // =============================================
                    // CHECK API STATUS
                    // =============================================

                    if (intStatus != 200)
                    {
                        objResponse.Respons =
                            enmResponse.Failed;

                        objResponse.Message =
                            string.IsNullOrWhiteSpace(
                                strMessage
                            )
                            ? "TRACES server error."
                            : strMessage;

                        return objResponse;
                    }


                    // =============================================
                    // TOTAL PAGES
                    // =============================================

                    int intReturnedPages = 1;

                    if (objJSON["totalPages"] != null)
                    {
                        int.TryParse(
                            Convert.ToString(
                                objJSON["totalPages"]
                            ),
                            out intReturnedPages
                        );
                    }

                    if (intReturnedPages <= 0)
                        intReturnedPages = 1;

                    intTotalPages =
                        intReturnedPages;


                    // =============================================
                    // PROCESS DATA ARRAY
                    // =============================================

                    JArray arrData =
                        objJSON["data"] as JArray;


                    if (arrData != null)
                    {
                        foreach (JToken token in arrData)
                        {
                            JObject item =
                                token as JObject;

                            if (item == null)
                                continue;


                            DataRow dRow =
                                table.NewRow();


                            // -------------------------------------
                            // Token / Acknowledgement Number
                            // -------------------------------------

                            dRow["Token Number"] =
                                Convert.ToString(
                                    item["ackNumber"]
                                );


                            // -------------------------------------
                            // Financial Year
                            // -------------------------------------

                            dRow["Finnancial Year"] =
                                Convert.ToString(
                                    item["financialYear"]
                                );


                            // -------------------------------------
                            // Original / Correction etc.
                            // -------------------------------------

                            dRow["Statement Type"] =
                                Convert.ToString(
                                    item["filingType"]
                                );


                            // -------------------------------------
                            // Form
                            // API returns 138 / 140 / 143 / 144
                            // -------------------------------------

                            string strReturnedForm =
                                Convert.ToString(
                                    item["formType"]
                                );

                            dRow["Form Type"] =
                                GetFormNameFromNumber(
                                    strReturnedForm
                                );


                            // -------------------------------------
                            // Quarter
                            // -------------------------------------

                            dRow["Quarter"] =
                                Convert.ToString(
                                    item["quarter"]
                                );


                            // -------------------------------------
                            // Filing Date
                            // -------------------------------------

                            dRow["Date of Filling"] =
                                Convert.ToString(
                                    item["filingDate"]
                                );


                            // -------------------------------------
                            // New API currently does not return it
                            // -------------------------------------

                            dRow["Date of Processing"] =
                                "";


                            // -------------------------------------
                            // Status
                            // Example:
                            // Processed without Default
                            // -------------------------------------

                            dRow["Status"] =
                                Convert.ToString(
                                    item["status"]
                                );


                            // -------------------------------------
                            // Keep reqId for View Details
                            // -------------------------------------

                            dRow["Request Id"] =
                                Convert.ToString(
                                    item["reqId"]
                                );


                            table.Rows.Add(
                                dRow
                            );
                        }
                    }


                    intPage++;
                }
                while (intPage < intTotalPages);


                // =====================================================
                // SUCCESS
                // =====================================================

                objResponse.Respons =
                    enmResponse.Success;

                objResponse.Message =
                    "Success";
            }
            catch (WebException ex)
            {
                HttpWebResponse response =
                    ex.Response as HttpWebResponse;


                if (response != null)
                {
                    int intStatusCode =
                        (int)response.StatusCode;


                    if (response.StatusCode ==
                            HttpStatusCode.Unauthorized ||
                        response.StatusCode ==
                            HttpStatusCode.Forbidden ||
                        intStatusCode == 410)
                    {
                        objResponse.Respons =
                            enmResponse.SessionTimeout;
                    }
                    else
                    {
                        objResponse.Respons =
                            enmResponse.Failed;
                    }
                }
                else
                {
                    objResponse.Respons =
                        enmResponse.Failed;
                }


                objResponse.Message =
                    ex.Message;
            }
            catch (Exception err)
            {
                if (Regex.IsMatch(
                        err.Message,
                        "410"))
                {
                    objResponse.Respons =
                        enmResponse.SessionTimeout;
                }
                else
                {
                    objResponse.Respons =
                        enmResponse.Failed;
                }

                objResponse.Message =
                    err.Message;
            }


            return objResponse;
        }

        #endregion

        #region makeHTTPPostJsonRequestWithoutToken

        private string makeHTTPPostJsonRequestWithoutToken(
            string strURL,
            string strJSON,
            string strReferer)
        {
            HttpWebRequest request =
                (HttpWebRequest)WebRequest.Create(
                    strURL
                );

            request.Method = "POST";

            request.ContentType =
                "application/json; charset=utf-8";

            request.Accept = "*/*";

            request.Referer = strReferer;

            request.UserAgent =
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) " +
                "AppleWebKit/537.36 (KHTML, like Gecko) " +
                "Chrome/141.0.0.0 Safari/537.36";

            request.AutomaticDecompression =
                DecompressionMethods.GZip |
                DecompressionMethods.Deflate;

            request.Headers.Add(
                "Origin",
                "https://traces.tdscpc.gov.in"
            );

            request.Headers.Add(
                "Cache-Control",
                "no-cache"
            );

            request.Headers.Add(
                "Pragma",
                "no-cache"
            );

            byte[] arrBytes =
                Encoding.UTF8.GetBytes(
                    strJSON
                );

            request.ContentLength =
                arrBytes.Length;

            using (Stream requestStream =
                   request.GetRequestStream())
            {
                requestStream.Write(
                    arrBytes,
                    0,
                    arrBytes.Length
                );
            }

            using (HttpWebResponse response =
                   (HttpWebResponse)request.GetResponse())
            {
                using (Stream responseStream =
                       response.GetResponseStream())
                {
                    using (StreamReader reader =
                           new StreamReader(responseStream))
                    {
                        return reader.ReadToEnd();
                    }
                }
            }
        }

        #endregion

        #region makeHTTPPostJsonRequest

        private string makeHTTPPostJsonRequest(
            string strURL,
            string strJSON,
            string strReferer,
            string strToken)
        {
            HttpWebRequest request =
                (HttpWebRequest)WebRequest.Create(
                    strURL
                );

            request.Method = "POST";

            request.ContentType =
                "application/json; charset=utf-8";

            request.Accept = "*/*";

            request.Referer = strReferer;

            request.UserAgent =
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) " +
                "AppleWebKit/537.36 (KHTML, like Gecko) " +
                "Chrome/141.0.0.0 Safari/537.36";

            request.AutomaticDecompression =
                DecompressionMethods.GZip |
                DecompressionMethods.Deflate;

            request.Headers.Add(
                "Origin",
                "https://traces.tdscpc.gov.in"
            );

            request.Headers.Add(
                "Cache-Control",
                "no-cache"
            );

            request.Headers.Add(
                "Pragma",
                "no-cache"
            );

            // -------------------------------------
            // AUTHORIZATION TOKEN
            // -------------------------------------

            string strAuthorization =
                Convert.ToString(strToken).Trim();

            if (!strAuthorization.StartsWith(
                    "Bearer ",
                    StringComparison.OrdinalIgnoreCase))
            {
                strAuthorization =
                    "Bearer " + strAuthorization;
            }

            request.Headers.Add(
                "Authorization",
                strAuthorization
            );

            // -------------------------------------

            byte[] arrBytes =
                Encoding.UTF8.GetBytes(
                    strJSON
                );

            request.ContentLength =
                arrBytes.Length;

            using (Stream requestStream =
                   request.GetRequestStream())
            {
                requestStream.Write(
                    arrBytes,
                    0,
                    arrBytes.Length
                );
            }

            using (HttpWebResponse response =
                   (HttpWebResponse)request.GetResponse())
            {
                using (Stream responseStream =
                       response.GetResponseStream())
                {
                    using (StreamReader reader =
                           new StreamReader(responseStream))
                    {
                        return reader.ReadToEnd();
                    }
                }
            }
        }

        #endregion

        #region NormalizeQuarterForFiledForms

        private string NormalizeQuarterForFiledForms(
            string strQuarter)
        {
            if (string.IsNullOrWhiteSpace(strQuarter))
                return "";

            strQuarter =
                strQuarter.Trim().ToUpper();

            switch (strQuarter)
            {
                case "1":
                case "01":
                case "Q1":
                    return "Q1";

                case "2":
                case "02":
                case "Q2":
                    return "Q2";

                case "3":
                case "03":
                case "Q3":
                    return "Q3";

                case "4":
                case "04":
                case "Q4":
                    return "Q4";

                default:
                    return strQuarter;
            }
        }

        #endregion

        #region GetFormNameFromNumber

        private string GetFormNameFromNumber(
            string strForm)
        {
            switch (strForm)
            {
                case "138":
                    return "24Q";

                case "140":
                    return "26Q";

                case "143":
                    return "27EQ";

                case "144":
                    return "27Q";

                default:
                    return strForm;
            }
        }

        #endregion

