                if (!objTraceData.panAmtValueCheck)
                {
                    sbParameter.Append("&pan1=" + objTraceData.PAN1);
                    sbParameter.Append("&amt1=" + objTraceData.PAN1Amount);
                    sbParameter.Append("&pan2=" + objTraceData.PAN2);
                    sbParameter.Append("&amt2=" + objTraceData.PAN2Amount);
                    sbParameter.Append("&pan3=" + objTraceData.PAN3);
                    sbParameter.Append("&amt3=" + objTraceData.PAN3Amount);
                }
                //--------------------------------------------------------------
                sbParameter.Append("&clickKYC=Proceed");
                sbParameter.Append("&dedkyc_SUBMIT=1");
                //--------------------------------------------------------------------------------------------------------------
                objNameval = TraceViewStateData(strResponse, "//form[@id=\"dedkyc\"]");
                //CHECKING ANY ERROR
                //----------------------------------------------------------
                foreach (KeyValuePair<string, string> pair in objNameval)
                {
                    sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
                    //if (pair.Key == "finYr")
                    //    sbParameter.Append("&" + pair.Key + "=" + pair.Value);

                    //if (pair.Key == "qrtr")
                    //    sbParameter.Append("&" + pair.Key + "=" + pair.Value);

                    //if (pair.Key == "frmType")
                    //    sbParameter.Append("&" + pair.Key + "=" + pair.Value);

                    //if (pair.Key == "tan")
                    //    sbParameter.Append("&" + pair.Key + "=" + pair.Value);

                    //if (pair.Key == "isChlnNil")
                    //    sbParameter.Append("&" + pair.Key + "=" + pair.Value);

                    //if (pair.Key == "dedCount")
                    //    sbParameter.Append("&" + pair.Key + "=" + pair.Value);

                    ////if (pair.Key == "bkEntryValue")
                    ////    sbParameter.Append("&" + pair.Key + "=" + pair.Value);

                    //if (pair.Key == "javax.faces.ViewState")
                    //    sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
                }
                //---------------------------------------------------------------
                if (objNameval.Count <= 0)
                {
                    objResponse.Message = "Server Error";
                    objResponse.Respons = enmResponse.SessionTimeout;
                    Logoff();
                    return objResponse;
                }
                //---------------------------------------------------------------
                strResponse = makeHTTPPostRequest(strBaseURL + "ded/kyc3form.xhtml", sbParameter);

                if (!IsStringExists(strResponse, "//form[@id=\"dedkyc\"]"))
                {
                    objResponse.Message = "Server Error";
                    objResponse.Respons = enmResponse.SessionTimeout;
                    this.Logoff();
                    return objResponse;
                }

                objResponse = IsServerError(strResponse, "//div[@id=\"err_Summary\"]");

                if (objResponse.Respons == enmResponse.Failed)
                {
                    // objResponse.ErrorMessage = "Server Error";
                    objResponse.Respons = enmResponse.Failed;
                    this.Logoff();
                    return objResponse;
                }
                //---------------------------------------------------------------------------------------------------------
                string strAuthenCode = RetrieveElementValue(strResponse, "//form[@id=\"dedkyc\"]", "//input[@id=\"authcode\"]", enmElementType.Value);

                objNameval = TraceViewStateData(strResponse, "//form[@id=\"dedkyc\"]");
                //CHECKING ANY ERROR
                sbParameter = new StringBuilder();
                //----------------------------------------------------------
                sbParameter.Append("authcode=" + HttpUtility.UrlEncode(strAuthenCode.Trim()));
                sbParameter.Append("&redirect=" + HttpUtility.UrlEncode("Proceed with Transaction"));
                sbParameter.Append("&dedkyc_SUBMIT=1");

                foreach (KeyValuePair<string, string> pair in objNameval)
                {
                    if (pair.Key == "javax.faces.ViewState")
                        sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
                }
                //-------------------------------------------------------------------------------------------------
                strResponse = makeHTTPPostRequest(strBaseURL + "ded/kyc3confirm.xhtml", sbParameter);

                objNameval = TraceViewStateData(strResponse, "//form[@id=\"downloadreqspec\"]");
                //CHECKING ANY ERROR
                sbParameter = new StringBuilder();
                //----------------------------------------------------------
                foreach (KeyValuePair<string, string> pair in objNameval)
                {
                    if (pair.Key == "finYr")
                        sbParameter.Append("fy=" + pair.Value);

                    if (pair.Key == "qrtr")
                    {
                        if (pair.Value == "")
                            sbParameter.Append("&qr=0");
                        else
                            sbParameter.Append("&qr=" + pair.Value);
                    }

                    if (pair.Key == "formType")
                        sbParameter.Append("&ft=" + pair.Value);

                    if (pair.Key == "dwldType")
                        sbParameter.Append("&dt=" + pair.Value);

                }
                //-------------------------------------------------------------------------------------------------
                //-- ANIK 2013-07-13
                //strResponse = makeHTTPGetRequest(strBaseURL + "CreateDwnldReqServlet?" + sbParameter.ToString());
                //-- ANIK 2013-07-28
                //strResponse = makeHTTPGetRequest(strBaseURL + "ded/srv/CreateDwnldReqServlet?" + sbParameter.ToString());
                strResponse = makeHTTPGetRequest(strBaseURL + "srv/CreateDwnldReqServlet?" + sbParameter.ToString());
                string strMessage = RetrieveElementValue(strResponse, "//div[@class='margintop20']", "//h5", enmElementType.InnerText);
                //-------------------------------------------------------------------------------------------------
                TracesResponse resp1 = new TracesResponse();
                //TracesResponse resp2 = new TracesResponse();
                int intIndex = 0;
                if (!string.IsNullOrEmpty(strMessage))
                {
                    if (objTraceData.AddlReqConsoFile)
                    {
                        resp1 = RequestForAddlConsoFile(objTraceData);
                        if (resp1.Respons == enmResponse.Success)
                        {
                            strMessage = "Justification Report, Conso file";
                            intIndex++;
                        }
                    }
                    if (objTraceData.AddlReqForm16AFile)
                    {
                        resp1 = RequestForAddlForm16A(objTraceData);
                        if (resp1.Respons == enmResponse.Success)
                        {
                            if (intIndex == 1)
                                strMessage += ", Form 16A";
                            else
                                strMessage = "Justification Report, Form 16A";
                            intIndex++;
                        }
                    }
                    if (objTraceData.AddlReqForm16File)
                    {
                        resp1 = RequestForAddlForm16(objTraceData);
                        if (resp1.Respons == enmResponse.Success)
                        {
                            if (intIndex == 1)
                                strMessage += ", Form 16 - Part A";
                            else
                                strMessage = "Justification Report, Form 16 - Part A";
                            intIndex++;
                        }
                    }
                    if (objTraceData.AddlReqForm27DFile)
                    {
                        resp1 = RequestForAddlForm27D(objTraceData);
                        if (resp1.Respons == enmResponse.Success)
                        {
                            if (intIndex == 1)
                                strMessage += ", Form 27D";
                            else
                                strMessage = "Justification Report, Form 27D";
                            intIndex++;
                        }
                    }
                    //------------------------------------------------
                    //RequestStatus conso = new RequestStatus();
                    //conso.AuthenticationCode = strAuthenCode;

                    //strMessage += Environment.NewLine + resp1.Message;
                    //strMessage += Environment.NewLine + resp2.Message;

                    if (intIndex > 0)
                        strMessage += " has been requested successfully";

                    //conso.StatusMessage = strMessage;

                    // objResponse.CustomeTypes = conso;
                    objResponse.Message = strMessage;
                    objResponse.Respons = enmResponse.Success;
                }
                //==============================================
                this.Logoff();
            }
            catch (Exception err)
            {
                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = err.Message;
                this.Logoff();
            }
            return objResponse;

        }

        #endregion

        #region RequestForJustificationReportDownloadIT2025
        public TracesResponse RequestForJustificationReportDownloadIT2025(
            TracesLogin objLogin,
            TracesData objTraceData)
        {
            TracesResponse objResponse = new TracesResponse();

            try
            {
                //---------------------------------------------------------
                // STEP 1 : VALIDATE INPUT OBJECTS
                //---------------------------------------------------------
                if (objLogin == null)
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message =
                        "TRACES login information is not available.";

                    return objResponse;
                }

                if (objTraceData == null)
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message =
                        "Statement information is not available.";

                    return objResponse;
                }

                //---------------------------------------------------------
                // STEP 2 : LOGIN TO TRACES IF SESSION DOES NOT EXIST
                //---------------------------------------------------------
                if (!IsSessionExists)
                {
                    objResponse =
                        this.makeLoginToTraces_New(objLogin);

                    if (objResponse.Respons == enmResponse.Failed)
                        return objResponse;
                }

                //---------------------------------------------------------
                // STEP 3 : VALIDATE LOGIN DETAILS
                //---------------------------------------------------------
                if (string.IsNullOrWhiteSpace(objLogin.UserID))
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message =
                        "TRACES User ID is not available.";

                    return objResponse;
                }

                if (string.IsNullOrWhiteSpace(objLogin.TAN))
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message =
                        "TAN is not available.";

                    return objResponse;
                }

                //---------------------------------------------------------
                // STEP 4 : PREPARE TRACES API VALUES
                //---------------------------------------------------------
                string strUserID =
                    objLogin.UserID.Trim();

                string strTAN =
                    objLogin.TAN.Trim();

                // New API expects 2026, not 2026-27.
                string strAssessmentYear =
                    GetJustificationAssessmentYearIT2025(
                        objTraceData.FAYear);

                // New API expects 138 / 140 / 143 / 144.
                //string strFormType = GetJustificationFormCodeIT2025(objTraceData.Forms);
                string strFormType = objTraceData.Forms;

                // New API expects 3 / 4 / 5 / 6.
                string strQuarter =
                    GetJustificationQuarterCodeIT2025(
                        objTraceData.Quarter);

                if (string.IsNullOrEmpty(strAssessmentYear))
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message =
                        "Invalid Tax Year.";

                    return objResponse;
                }

                if (string.IsNullOrEmpty(strFormType))
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message =
                        "Invalid Form Type.";

                    return objResponse;
                }

                if (string.IsNullOrEmpty(strQuarter))
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message =
                        "Invalid Quarter.";

                    return objResponse;
                }

                //---------------------------------------------------------
                // STEP 5 : BUILD ACKNOWLEDGEMENT NUMBER
                //
                // Captured TRACES payload example:
                //
                // TAN              = CALP04665D
                // Form Type        = 140
                // Quarter          = 3
                // Acknowledgement  = CALP04665D14Q01
                //
                // This is generated internally. The user does not need
                // to enter it.
                //---------------------------------------------------------
                string strAcknowledgementNumber =
                    BuildJustificationAcknowledgementNumberIT2025(
                        strTAN,
                        strFormType,
                        strQuarter);

                //---------------------------------------------------------
                // STEP 6 : INITIATE JUSTIFICATION REPORT REQUEST
                //---------------------------------------------------------
                string strInitiateResponse =
                    InitiateJustificationReportRequestIT2025(
                        strUserID,
                        strTAN,
                        strAssessmentYear,
                        strQuarter,
                        strFormType,
                        strAcknowledgementNumber);

                if (string.IsNullOrWhiteSpace(strInitiateResponse))
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message =
                        "No response received from TRACES while "
                        + "initiating the Justification Report request.";

                    return objResponse;
                }

                //---------------------------------------------------------
                // STEP 7 : PARSE ARRAY RESPONSE
                //
                // Response example:
                //
                // [
                //   {
                //     "certDownloadStatus":1,
                //     "requestId":250359250,
                //     "status":"Request Initiated"
                //   }
                // ]
                //---------------------------------------------------------
                dynamic objJSON =
                    Newtonsoft.Json.JsonConvert.DeserializeObject(
                        strInitiateResponse);

                if (objJSON == null ||
                    objJSON.Count == 0 ||
                    objJSON[0] == null ||
                    objJSON[0].requestId == null)
                {
                    objResponse.Respons = enmResponse.Failed;

                    objResponse.Message =
                        "Justification Report request was submitted, "
                        + "but the Request ID was not returned by TRACES."
                        + Environment.NewLine
                        + Environment.NewLine
                        + "TRACES Response:"
                        + Environment.NewLine
                        + strInitiateResponse;

                    return objResponse;
                }

                //---------------------------------------------------------
                // STEP 8 : EXTRACT REQUEST ID AND STATUS
                //---------------------------------------------------------
                string strRequestID =
                    Convert.ToString(
                        objJSON[0].requestId);

                string strStatus = "";

                if (objJSON[0].status != null)
                {
                    strStatus =
                        Convert.ToString(
                            objJSON[0].status);
                }

                if (string.IsNullOrWhiteSpace(strRequestID))
                {
                    objResponse.Respons = enmResponse.Failed;

                    objResponse.Message =
                        "Justification Report request was submitted, "
                        + "but the Request ID returned by TRACES is blank."
                        + Environment.NewLine
                        + Environment.NewLine
                        + "TRACES Response:"
                        + Environment.NewLine
                        + strInitiateResponse;

                    return objResponse;
                }

                //---------------------------------------------------------
                // STEP 9 : RETURN SUCCESS
                //---------------------------------------------------------
                objResponse.Respons =
                    enmResponse.Success;

                // The calling form will retrieve:
                //
                // strRequestNo = Convert.ToString(response.Data);
                objResponse.Data =
                    strRequestID;

                objResponse.Message =
                    "Justification Report request submitted successfully."
                    + Environment.NewLine
                    + Environment.NewLine
                    + "Request ID: "
                    + strRequestID;

                if (!string.IsNullOrWhiteSpace(strStatus))
                {
                    objResponse.Message +=
                        Environment.NewLine
                        + "Status: "
                        + strStatus;
                }

                return objResponse;
            }
            catch (WebException webEx)
            {
                this.bnlSessionExists = false;

                string strError =
                    webEx.Message;

                try
                {
                    if (webEx.Response != null)
                    {
                        using (StreamReader sr =
                            new StreamReader(
                                webEx.Response.GetResponseStream()))
                        {
                            string strServerError =
                                sr.ReadToEnd();

                            if (!string.IsNullOrWhiteSpace(strServerError))
                            {
                                strError +=
                                    Environment.NewLine
                                    + "TRACES Response: "
                                    + strServerError;
                            }
                        }
                    }
                }
                catch
                {
                }

                objResponse.Respons =
                    enmResponse.Failed;

                objResponse.Message =
                    strError;

                return objResponse;
            }
            catch (Exception err)
            {
                this.bnlSessionExists = false;

                objResponse.Respons =
                    enmResponse.Failed;

                objResponse.Message =
                    err.Message;

                return objResponse;
            }
        }

        #endregion

        #region InitiateJustificationReportRequestIT2025

        private string InitiateJustificationReportRequestIT2025(
            string userId,
            string tan,
            string assessmentYear,
            string quarter,
            string formType,
            string acknowledgementNumber)
        {
            string strURL =
                "https://traces-app.tdscpc.gov.in/"
                + "tanjustreportservice/api/justification/initiateDownload";

            //---------------------------------------------------------
            // IMPORTANT:
            // The TRACES API expects an array containing one object.
            //---------------------------------------------------------
            string strJSON =
                "[{"
                + "\"userId\":\""
                + EscapeJsonValueIT2025(userId)
                + "\","

                + "\"acknowledgementNumber\":\""
                + EscapeJsonValueIT2025(acknowledgementNumber)
                + "\","

                + "\"formType\":\""
                + EscapeJsonValueIT2025(formType)
                + "\","

                + "\"assessmentYear\":\""
                + EscapeJsonValueIT2025(assessmentYear)
                + "\","

                + "\"quarter\":\""
                + EscapeJsonValueIT2025(quarter)
                + "\","

                + "\"deductorTan\":\""
                + EscapeJsonValueIT2025(tan)
                + "\""

                + "}]";

            return makeHTTPPostJSONRequest_IT2025(
                strURL,
                strJSON);
        }

        #endregion

        #region GetJustificationAssessmentYearIT2025

        private string GetJustificationAssessmentYearIT2025(
            string financialYear)
        {
            if (string.IsNullOrWhiteSpace(financialYear))
                return "";

            string strYear =
                financialYear.Trim();

            // Handles 2026-27.
            if (strYear.Contains("-"))
            {
                string[] arrYear =
                    strYear.Split('-');

                if (arrYear.Length > 0)
                    strYear = arrYear[0];
            }

            // Handles any accidental spaces or longer values.
            if (strYear.Length >= 4)
                strYear = strYear.Substring(0, 4);

            int intYear;

            if (!int.TryParse(strYear, out intYear))
                return "";

            return intYear.ToString();
        }

        #endregion
        
        #region GetJustificationQuarterCodeIT2025

        private string GetJustificationQuarterCodeIT2025(
            string quarter)
        {
            if (string.IsNullOrWhiteSpace(quarter))
                return "";

            string strQuarter =
                quarter.Trim().ToUpper();

            //---------------------------------------------------------
            // Existing TDSMAN already stores quarter as 3 / 4 / 5 / 6
            //---------------------------------------------------------
            if (strQuarter == "3" ||
                strQuarter == "4" ||
                strQuarter == "5" ||
                strQuarter == "6")
            {
                return strQuarter;
            }

            //---------------------------------------------------------
            // Also support Q1 / Q2 / Q3 / Q4
            //---------------------------------------------------------
            switch (strQuarter)
            {
                case "Q1":
                case "1":
                    return "3";

                case "Q2":
                case "2":
                    return "4";

                case "Q3":
                    return "5";

                case "Q4":
                    return "6";

                default:
                    return "";
            }
        }

        #endregion

        #region BuildJustificationAcknowledgementNumberIT2025

        private string BuildJustificationAcknowledgementNumberIT2025(
            string tan,
            string formType,
            string quarter)
        {
            if (string.IsNullOrWhiteSpace(tan) ||
                string.IsNullOrWhiteSpace(formType) ||
                string.IsNullOrWhiteSpace(quarter))
            {
                return "";
            }

            string strTAN =
                tan.Trim().ToUpper();

            string strFormType =
                formType.Trim();

            string strQuarter =
                quarter.Trim();

            //---------------------------------------------------------
            // Captured TRACES format:
            //
            // Form 140 > 14
            //---------------------------------------------------------
            string strFormPart =
                strFormType;

            if (strFormPart.Length >= 2)
                strFormPart = strFormPart.Substring(0, 2);

            //---------------------------------------------------------
            // TDSMAN/API quarter mapping:
            //
            // 3 > Q01
            // 4 > Q02
            // 5 > Q03
            // 6 > Q04
            //---------------------------------------------------------
            int intQuarterCode;

            if (!int.TryParse(strQuarter, out intQuarterCode))
                return "";

            int intActualQuarter =
                intQuarterCode - 2;

            if (intActualQuarter < 1 ||
                intActualQuarter > 4)
            {
                return "";
            }

            return strTAN
                + strFormPart
                + "Q"
                + intActualQuarter.ToString("00");
        }

        #endregion

        #region EscapeJsonValueIT2025

        private string EscapeJsonValueIT2025(
            string value)
        {
            if (value == null)
                return "";

            return value
                .Replace("\\", "\\\\")
                .Replace("\"", "\\\"")
                .Replace("\r", "\\r")
                .Replace("\n", "\\n")
                .Replace("\t", "\\t");
        }

        #endregion

        #region DownloadJustificationReportIT2025

        public TracesResponse DownloadJustificationReportIT2025(
            int requestId,
            string downloadFolder)
        {
            TracesResponse objResponse = new TracesResponse();

            try
            {
                string url =
                    "https://traces-app.tdscpc.gov.in/"
                    + "tanjustreportservice/api/justification/"
                    + "downloadFile?requestId="
                    + requestId;

                request = (HttpWebRequest)WebRequest.Create(url);

                request.Method = "GET";
                request.KeepAlive = true;
                request.CookieContainer = objContainer;

                request.UserAgent =
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/138.0 Safari/537.36";

                request.Accept =
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,*/*";

                request.Headers.Add(
                    "Authorization",
                    "Bearer " + tracesAuthToken);

                request.Referer =
                    "https://traces.tdscpc.gov.in/auth/justificationReport/downloadScreen";

                response = (HttpWebResponse)request.GetResponse();

                objContainer.Add(response.Cookies);

                //----------------------------------------------------
                // CHECK RESPONSE TYPE
                //----------------------------------------------------
                string contentType = response.ContentType.ToLower();

                if (contentType.Contains("application/json"))
                {
                    string jsonResponse = "";

                    using (StreamReader sr =
                        new StreamReader(response.GetResponseStream()))
                    {
                        jsonResponse = sr.ReadToEnd();
                    }

                    objResponse.Respons = enmResponse.Failed;

                    //----------------------------------------------------
                    // Default message
                    //----------------------------------------------------
                    objResponse.Message =
                        "Justification Report is not available for the selected statement.";

                    try
                    {
                        dynamic objJson =
                            JsonConvert.DeserializeObject(jsonResponse);

                        if (objJson != null)
                        {
                            //------------------------------------------------
                            // TRACES may return:
                            // message
                            // error
                            // errors[0].message
                            //------------------------------------------------

                            if (objJson.message != null)
                            {
                                objResponse.Message =
                                    Convert.ToString(objJson.message);
                            }
                            else if (objJson.error != null)
                            {
                                objResponse.Message =
                                    Convert.ToString(objJson.error);
                            }
                            else if (objJson.errors != null &&
                                     objJson.errors.Count > 0 &&
                                     objJson.errors[0].message != null)
                            {
                                objResponse.Message =
                                    Convert.ToString(objJson.errors[0].message);
                            }
                        }
                    }
                    catch
                    {
                        // Ignore JSON parsing errors and keep default message.
                    }

                    return objResponse;
                }

                //----------------------------------------------------
                // filename
                //----------------------------------------------------

                string fileName = "";

                string disposition =
                    response.Headers["Content-Disposition"];

                if (!string.IsNullOrEmpty(disposition))
                {
                    Match m =
                        Regex.Match(
                            disposition,
                            "filename=\"?(.*?)\"?$");

                    if (m.Success)
                        fileName = m.Groups[1].Value;
                }

                if (string.IsNullOrWhiteSpace(fileName))
                {
                    fileName =
                        "JustificationReport_"
                        + requestId
                        + ".xlsx";
                }

                string fullPath =
                    Path.Combine(
                        downloadFolder,
                        fileName);

                using (FileStream fs =
                    new FileStream(
                        fullPath,
                        FileMode.Create,
                        FileAccess.Write))
                {
                    response
                        .GetResponseStream()
                        .CopyTo(fs);
                }

                objResponse.Respons =
                    enmResponse.Success;

                objResponse.Message =
                    "Justification Report downloaded successfully.";

                objResponse.Data = fullPath;

                return objResponse;
            }
            catch (Exception ex)
            {
                objResponse.Respons =
                    enmResponse.Failed;

                objResponse.Message =
                    ex.Message;

                return objResponse;
            }
        }

