                sbParameter.Append("&quarter=" + objTraceData.Quarter);
                sbParameter.Append("&formType=" + objTraceData.Forms);
                //
                ArrayList objPANList = new ArrayList();
                objPANList.Add("AAAAR5112K");
                objPANList.Add("AAACL4984F");
                sbParameter.Append("&panList=" + objPANList);
                //
                sbParameter.Append("&clickGo=Go");
                sbParameter.Append("&bulkSearch_SUBMIT=1");
                //sbParameter.Append("&searchPAN_SUBMIT=1");
                /* --------------------------------------------------------------------
