        //-- ARUP @ 2014-05-08
        public TracesResponse makeLoginToTRACES(TracesLogin login)
        {
            TracesResponse objResponse = new TracesResponse();

            //CREATE DATA FOR LOGIN FORM
            StringBuilder sbParameter = new StringBuilder();
            try
            {
                //sbParameter.Append("username=" + login.UserID);
                //sbParameter.Append("&j_username=" + login.UserID + "^" + login.TAN);
                //sbParameter.Append("&j_password=" + HttpUtility.UrlEncode(login.Password));
                //sbParameter.Append("&j_tanPan=" + login.TAN);
                //sbParameter.Append("&j_captcha=" + login.CaptchaCode);
                ////-- ARUP - 2016/07/19
                //sbParameter.Append("username=" + HttpUtility.UrlEncode(login.UserID));
                //sbParameter.Append("&j_username=" + HttpUtility.UrlEncode(login.UserID) + "^" + login.TAN);
                //sbParameter.Append("&j_password=" + HttpUtility.UrlEncode(login.Password));
                //sbParameter.Append("&j_tanPan=" + login.TAN);
                //sbParameter.Append("&j_captcha=" + login.CaptchaCode);
                //-- ARUP - 2018/03/22
                sbParameter.Append("search1=on");
                sbParameter.Append("&username=" + HttpUtility.UrlEncode(login.UserID));
                sbParameter.Append("&j_username=" + HttpUtility.UrlEncode(login.UserID) + "^" + login.TAN);
                sbParameter.Append("&selradio=D");
                sbParameter.Append("&j_password=" + HttpUtility.UrlEncode(login.Password));
                sbParameter.Append("&j_tanPan=" + login.TAN);
                sbParameter.Append("&j_captcha=" + login.CaptchaCode);

                //MAKE REQUEST TO LOGIN FORM
                strServerResponse = makeHTTPPostRequest(strBaseURL + "j_security_check", sbParameter);

                if (string.IsNullOrEmpty(strServerResponse))
                {
                    IsSessionExists = false;
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message = "Login Failed or Server Error";
                    return objResponse;
                }

                //
                //form[@id=\"dedkyc\"]
                objResponse = IsServerError(strServerResponse, "//form[@id=\"surveyForm\"]");

                if (objResponse.Respons == enmResponse.Failed)
                {
                    IsSessionExists = false;
                    objResponse.Message = "Please log into your account by visiting www.tdscpc.gov.in and fill the survey form.";
                    return objResponse;
                }

                //CHECKING ANY ERROR FROM SERVER
                objResponse = IsServerError(strServerResponse, "//span[@id=\"err_Summary\"]");

                if (objResponse.Respons == enmResponse.Failed)
                {
                    IsSessionExists = false;
                    objResponse.Message = "Login Failed or Server Error";
                    return objResponse;
                }
                //-- ANIK 2022/02/18
                //if (!IsConditionMatch(strServerResponse, login.TAN))
                //{
                //    objResponse.Respons = enmResponse.Failed;
                //    objResponse.Message = "Login Failed or Server Error";
                //    return objResponse;
                //}
                else
                {
                    IsSessionExists = true;
                    objResponse.Respons = enmResponse.Success;
                    objResponse.Message = "";
                    return objResponse;
                }

            }
            catch (Exception err)
            {
                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = err.Message;
                return objResponse;
            }

        }

        public string HttpGetOneLogin(string url)
        {
            HttpWebRequest req = (HttpWebRequest)WebRequest.Create(url);
            req.Method = "GET";
            req.AllowAutoRedirect = true;
            req.KeepAlive = true;
            req.UserAgent = "Mozilla/5.0";
            req.CookieContainer = TracesSession.CookieJar;

            HttpWebResponse resp = (HttpWebResponse)req.GetResponse();
            TracesSession.CookieJar.Add(resp.Cookies);

            using (var s = resp.GetResponseStream())
            using (var r = new StreamReader(s))
                return r.ReadToEnd();
        }

        public TracesResponse LoginToTraces_OneLogin(TracesLogin login)
        {
            TracesResponse result = new TracesResponse();

            try
            {
                // STEP 1: Load login.xhtml
                string loginHtml = makeHTTPGetRequestOneLogin("https://www.tdscpc.gov.in/app/login.xhtml");

                // Extract ViewState
                string viewState = ExtractViewState(loginHtml);
                if (string.IsNullOrEmpty(viewState))
                {
                    result.Respons = enmResponse.Failed;
                    result.Message = "Unable to extract ViewState from TRACES.";
                    return result;
                }

                // STEP 2: Build POST Data
                ////StringBuilder sb = new StringBuilder();
                ////sb.Append("search=on");
                ////sb.Append("&j_username=").Append(HttpUtility.UrlEncode(login.UserID));
                ////sb.Append("&deductor_PAN_TAN=").Append(HttpUtility.UrlEncode(login.TAN));
                ////sb.Append("&j_password=").Append(HttpUtility.UrlEncode(login.Password));
                ////sb.Append("&captchaCode=").Append(HttpUtility.UrlEncode(login.CaptchaCode));
                ////sb.Append("&javax.faces.ViewState=").Append(HttpUtility.UrlEncode(viewState));
                string postUrl = "https://www.tdscpc.gov.in/app/j_security_check";

                //// STEP 3: Submit login
                //string postResponse = makeHTTPPostRequestOneLogin(
                //    "https://www.tdscpc.gov.in/app/j_spring_security_check",
                //    sb.ToString());
                StringBuilder sb = new StringBuilder();
                sb.Append("j_username=").Append(HttpUtility.UrlEncode(login.UserID + "^" + login.TAN));
                sb.Append("&j_password=").Append(HttpUtility.UrlEncode(login.Password));
                sb.Append("&j_tanPan=").Append(HttpUtility.UrlEncode(login.TAN));
                sb.Append("&j_captcha=").Append(HttpUtility.UrlEncode(login.CaptchaCode));
                sb.Append("&selradio=D");
                sb.Append("&javax.faces.ViewState=").Append(HttpUtility.UrlEncode(viewState));
                sb.Append("&j_id27839938_263b8a84_SUBMIT=1");
                sb.Append("&ticker=");
                sb.Append("&username="); // required but ignored

                string postResponse = makeHTTPPostRequestOneLogin(postUrl, sb.ToString());
                

                // STEP 4: Detect JS redirect
                string jsRedirect = ExtractRedirectUrl(postResponse);

                if (!string.IsNullOrEmpty(jsRedirect))
                {
                    if (jsRedirect.StartsWith("/"))
                        jsRedirect = "https://www.tdscpc.gov.in" + jsRedirect;

                    // Follow redirect manually
                    postResponse = makeHTTPGetRequestOneLogin(jsRedirect);
                }

                // STEP 5: Check login success
                if (postResponse.Contains("CommunicationInboxForm"))
                {
                    TracesSession.IsLoggedIn = true;
                    TracesSession.LoginTime = DateTime.Now;
                    TracesSession.TAN = login.TAN;

                    result.Respons = enmResponse.Success;
                    result.Message = "Logged in successfully.";
                    return result;
                }

                if (postResponse.Contains("Invalid Captcha"))
                {
                    result.Respons = enmResponse.Failed;
                    result.Message = "Incorrect captcha.";
                    return result;
                }

                if (postResponse.Contains("Invalid UserId") ||
                    postResponse.Contains("Invalid Password"))
                {
                    result.Respons = enmResponse.Failed;
                    result.Message = "Invalid UserID or Password.";
                    return result;
                }

                result.Respons = enmResponse.Failed;
                result.Message = "Login failed. TRACES returned unknown page.";
                return result;
            }
            catch (Exception ex)
            {
                result.Respons = enmResponse.Failed;
                result.Message = "Login error: " + ex.Message;
                return result;
            }
        }


        private string ExtractViewState(string html)
        {
            //Match m = Regex.Match(html,
            //    "name=\"javax.faces.ViewState\" value=\"(.*?)\"");
            //if (m.Success)
            //    return m.Groups[1].Value;

            //return "";

            Match m = Regex.Match(html,
        "id=\"javax.faces.ViewState\"[^>]*value=\"([^\"]+)\"",
        RegexOptions.IgnoreCase);

            return m.Success ? m.Groups[1].Value : "";
        }

        private string ExtractRedirectUrl(string html)
        {
            Match m = Regex.Match(html, "window.location=['\"]([^'\"]+)['\"]");
            if (m.Success)
                return m.Groups[1].Value;
            return null;
        }



