        #region makeLoginToTraces_New
        public TracesResponse makeLoginToTraces_New(TracesLogin login)
        {
            TracesResponse result = new TracesResponse();

            try
            {
                //MessageBox.Show("1");
                //  DEBUG (optional - remove later)
                //MessageBox.Show(
                //    "CaptchaID: " + login.CaptchaId +
                //    "\nCaptcha: " + login.CaptchaCode
                //);

                var request = (HttpWebRequest)WebRequest.Create(
                    "https://traces-app.tdscpc.gov.in/loginservice/api/auth/login");
                //MessageBox.Show("1.1");
                request.Method = "POST";
                request.ContentType = "application/json";
                request.Accept = "application/json";
                request.UserAgent = "Mozilla/5.0";
                request.CookieContainer = TracesSession.CookieJar;   // SAME container
                request.KeepAlive = true;
                request.ProtocolVersion = HttpVersion.Version11;

                //  IMPORTANT HEADERS
                request.Headers.Add("Origin", "https://traces.tdscpc.gov.in");
                request.Referer = "https://traces.tdscpc.gov.in/";
                request.Headers.Add("Accept-Language", "en-US,en;q=0.9");
                request.Headers.Add("X-Requested-With", "XMLHttpRequest");

                //  PAYLOAD (FINAL)
                var payload = new
                {
                    userId = login.TAN,
                    password = login.Password,
                    captcha = login.CaptchaCode.Trim(),
                    captchaId = login.CaptchaId,
                    userType = "Deductor",   // 
                    subUser = false,
                    subUserPanId = ""
                };
                //MessageBox.Show("1.3");

                string json = Newtonsoft.Json.JsonConvert.SerializeObject(payload);

                using (var streamWriter = new StreamWriter(request.GetRequestStream()))
                {
                    streamWriter.Write(json);
                }
                //MessageBox.Show("1.4");
                var response = (HttpWebResponse)request.GetResponse();

                //  STORE COOKIES (VERY IMPORTANT)
                if (response.Cookies != null)
                    TracesSession.CookieJar.Add(response.Cookies);
                //MessageBox.Show("1.5");
                string responseText;
                using (var reader = new StreamReader(response.GetResponseStream()))
                {
                    responseText = reader.ReadToEnd();
                }
                //MessageBox.Show("1.6");
                dynamic obj = Newtonsoft.Json.JsonConvert.DeserializeObject(responseText);
                tracesAuthToken = obj.authTokenDto?.accessToken;

                // CALL PREAUTH (VERY IMPORTANT)
                callPreauth();
                //MessageBox.Show("1.7");
                // DEBUG (keep initially)
                //MessageBox.Show(responseText);

                //  SUCCESS CHECK
                if (responseText.ToLower().Contains("token") ||
                    responseText.ToLower().Contains("session") ||
                    responseText.ToLower().Contains("authenticated"))
                {
                    TracesSession.IsLoggedIn = true;
                    TracesSession.LoginTime = DateTime.Now;
                    TracesSession.TAN = login.TAN;

                    result.Respons = enmResponse.Success;
                    result.Message = "Login successful";
                    return result;
                }

                //  CAPTCHA ERROR
                if (responseText.ToLower().Contains("captcha"))
                {
                    result.Respons = enmResponse.Failed;
                    result.Message = "Invalid captcha";
                    return result;
                }

                //  CREDENTIAL ERROR
                if (responseText.ToLower().Contains("invalid"))
                {
                    result.Respons = enmResponse.Failed;
                    result.Message = "Invalid credentials";
                    return result;
                }

                result.Respons = enmResponse.Failed;
                result.Message = "Login failed - unknown response";
                return result;
            }
            catch (WebException ex)
            {
                string err = "";
                //
                if (ex.Response != null)
                {
                    using (var reader = new StreamReader(ex.Response.GetResponseStream()))
                    {
                        err = reader.ReadToEnd();
                    }
                }
                //
                result.Respons = enmResponse.Failed;
                var doc = JsonDocument.Parse(err);
                string message = doc.RootElement.GetProperty("message").GetString();
                err = message;
                //if (message.Contains("Verification code entered does not match with image data"))
                //{
                //    err = "Wrong Captcha entered";
                //}
                //else if (message.Contains("Invalid Password"))
                //{
                //    err = "Invalid Password";
                //}
                //else if (message.Contains("attempts left to enter correct"))
                //{
                //    err = message;// "Invalid Password";
                //}
                //
                //string msg = "ERROR:\n" + ex.Message;
                ////
                //if (ex.InnerException != null)
                //{
                //    msg += "\n\nINNER EXCEPTION:\n" + ex.InnerException.Message;
                //    msg += "\n\nSTACK TRACE:\n" + ex.InnerException.StackTrace;
                //}
                ////
                //MessageBox.Show(msg);
                result.Message = "Login error: " + err;
                //
                return result;
            }
        }
