        #region makeLoginToTraces_New2627

        public TracesResponse makeLoginToTraces_New2627(TracesLogin login)
        {
            TracesResponse result = new TracesResponse();

            try
            {
                var request = (HttpWebRequest)WebRequest.Create(
                    "https://traces-app.tdscpc.gov.in/loginservice/api/auth/login"
                );

                request.Method = "POST";
                request.ContentType = "application/json; charset=utf-8";
                request.Accept = "application/json";
                request.UserAgent = "Mozilla/5.0";

                // SAME SESSION COOKIE CONTAINER
                request.CookieContainer = TracesSession.CookieJar;

                request.KeepAlive = true;
                request.ProtocolVersion = HttpVersion.Version11;

                // --------------------------------------------------
                // HEADERS
                // --------------------------------------------------

                request.Headers.Add(
                    "Origin",
                    "https://traces.tdscpc.gov.in"
                );

                request.Referer =
                    "https://traces.tdscpc.gov.in/";

                request.Headers.Add(
                    "Accept-Language",
                    "en-US,en;q=0.9"
                );

                request.Headers.Add(
                    "X-Requested-With",
                    "XMLHttpRequest"
                );


                // --------------------------------------------------
                // LOGIN PAYLOAD
                // --------------------------------------------------

                var payload = new
                {
                    userId = login.TAN,

                    password = login.Password,

                    captcha =
                        login.CaptchaCode.Trim(),

                    captchaId =
                        login.CaptchaId,

                    userType =
                        "Deductor",

                    subUser =
                        false,

                    subUserPanId =
                        ""
                };


                string json =
                    Newtonsoft.Json.JsonConvert.SerializeObject(
                        payload
                    );


                // --------------------------------------------------
                // SEND REQUEST
                // --------------------------------------------------

                using (var streamWriter =
                       new StreamWriter(
                           request.GetRequestStream()))
                {
                    streamWriter.Write(json);
                }


                var response =
                    (HttpWebResponse)request.GetResponse();


                // --------------------------------------------------
                // STORE COOKIES
                // --------------------------------------------------

                if (response.Cookies != null)
                {
                    TracesSession.CookieJar.Add(
                        response.Cookies
                    );
                }


                // --------------------------------------------------
                // READ RESPONSE
                // --------------------------------------------------

                string responseText;

                using (var reader =
                       new StreamReader(
                           response.GetResponseStream()))
                {
                    responseText =
                        reader.ReadToEnd();
                }


                // --------------------------------------------------
                // PARSE LOGIN RESPONSE
                // --------------------------------------------------

                JObject obj =
                    JObject.Parse(responseText);


                bool isAuthenticated =
                    Convert.ToBoolean(
                        obj["isAuthenticated"] ?? false
                    );


                string status =
                    Convert.ToString(
                        obj["status"]
                    );


                string message =
                    Convert.ToString(
                        obj["message"]
                    );


                // --------------------------------------------------
                // STORE NEW TRACES API TOKENS
                // --------------------------------------------------

                JObject objAuthToken =
                    obj["authTokenDto"] as JObject;


                if (objAuthToken != null)
                {
                    strBearerToken =
                        Convert.ToString(
                            objAuthToken["accessToken"]
                        );

                    strRefreshToken =
                        Convert.ToString(
                            objAuthToken["refreshToken"]
                        );

                    // If tracesAuthToken is already being used
                    // elsewhere in your project, keep it synchronized.
                    tracesAuthToken =
                        strBearerToken;
                }


                // --------------------------------------------------
                // SUCCESS
                // --------------------------------------------------

                if (isAuthenticated &&
                    !string.IsNullOrWhiteSpace(
                        strBearerToken))
                {
                    // Existing PREAUTH call
                    callPreauth();


                    TracesSession.IsLoggedIn =
                        true;

                    TracesSession.LoginTime =
                        DateTime.Now;

                    TracesSession.TAN =
                        login.TAN;


                    result.Respons =
                        enmResponse.Success;

                    result.Message =
                        "Login successful";

                    return result;
                }


                // --------------------------------------------------
                // CAPTCHA ERROR
                // --------------------------------------------------

                if (!string.IsNullOrWhiteSpace(message) &&
                    message.ToLower().Contains("captcha"))
                {
                    result.Respons =
                        enmResponse.Failed;

                    result.Message =
                        "Invalid captcha";

                    return result;
                }


                // --------------------------------------------------
                // CREDENTIAL ERROR
                // --------------------------------------------------

                if (!string.IsNullOrWhiteSpace(message) &&
                    message.ToLower().Contains("invalid"))
                {
                    result.Respons =
                        enmResponse.Failed;

                    result.Message =
                        message;

                    return result;
                }


                // --------------------------------------------------
                // OTHER LOGIN FAILURE
                // --------------------------------------------------

                result.Respons =
                    enmResponse.Failed;

                result.Message =
                    string.IsNullOrWhiteSpace(message)
                    ? "Login failed - unknown response"
                    : message;

                return result;
            }
            catch (WebException ex)
            {
                string err = "";

                try
                {
                    if (ex.Response != null)
                    {
                        using (var reader =
                               new StreamReader(
                                   ex.Response.GetResponseStream()))
                        {
                            err =
                                reader.ReadToEnd();
                        }
                    }


                    if (!string.IsNullOrWhiteSpace(err))
                    {
                        JObject objError =
                            JObject.Parse(err);

                        string serverMessage =
                            Convert.ToString(
                                objError["message"]
                            );

                        if (!string.IsNullOrWhiteSpace(
                                serverMessage))
                        {
                            err =
                                serverMessage;
                        }
                    }
                }
                catch
                {
                    // If error response is not JSON,
                    // retain original WebException message.
                }


                result.Respons =
                    enmResponse.Failed;

                result.Message =
                    "Login error: " +
                    (
                        string.IsNullOrWhiteSpace(err)
                        ? ex.Message
                        : err
                    );

                return result;
            }
            catch (Exception ex)
            {
                result.Respons =
                    enmResponse.Failed;

                result.Message =
                    "Login error: " +
                    ex.Message;

                return result;
            }
        }

