            _handler.CookieContainer = new CookieContainer();
            _handler.UseCookies = true;

            _client = new HttpClient(_handler);
            _client.Timeout = TimeSpan.FromSeconds(30);
            _client.DefaultRequestHeaders.Add("User-Agent",
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64)");

            string url = "https://onlineservices.tin.egov.proteantech.in/TIN/UnAuthorizedView.do";

            var response = _client.GetAsync(url).Result;

            var captchaResponse = _client.GetAsync(
                "https://onlineservices.tin.egov.proteantech.in/TIN/CaptchaServlet"
            ).Result;

            return captchaResponse.Content.ReadAsStreamAsync().Result;
        }


        #region makeHTTPJSONRequest
        private string makeHTTPJSONRequest(string strURL)
        {
            request = (HttpWebRequest)WebRequest.Create(strURL);
            string json = "";
            request.ServicePoint.Expect100Continue = false;
            request.Method = "GET";
            request.UserAgent = "Mozilla/5.0 (Windows NT 5.1) AppleWebKit/537.17 (KHTML, like Gecko) Chrome/24.0.1312.57 Safari/537.17";
            request.ContentType = "application/json";
            request.Headers.Add("Cache-Control", "no-cache");
            //
            request.KeepAlive = true; //wasim
            //
            if (request.CookieContainer == null)
                request.CookieContainer = objContainer;

            response = (HttpWebResponse)request.GetResponse();
            request.CookieContainer.Add(response.Cookies);
            //--------------------------------------------------------------------
            using (Stream responseStream = response.GetResponseStream())
            {
                using (StreamReader responseReader = new StreamReader(responseStream))
                    json = responseReader.ReadToEnd();
            }
            //--------------------------------------------------------------------
            return json;
        }


        public string makeHTTPJSONRequest_New(string url)
        {
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);

            request.Method = "GET";
            request.Accept = "application/json, text/javascript, */*; q=0.01";
            request.UserAgent = "Mozilla/5.0";
            request.CookieContainer = TracesSession.CookieJar;
            request.KeepAlive = true;

            request.Headers.Add("X-Requested-With", "XMLHttpRequest");
            request.Headers.Add("Accept-Language", "en-US,en;q=0.9");

            HttpWebResponse response = (HttpWebResponse)request.GetResponse();

            if (response.Cookies != null)
                TracesSession.CookieJar.Add(response.Cookies);

            using (var stream = response.GetResponseStream())
            using (var reader = new StreamReader(stream))
            {
                return reader.ReadToEnd();
            }
        }

