        public CaptchaResult getCaptchaCodeOneLogin()
        {
            ServicePointManager.Expect100Continue = false;
            ServicePointManager.SecurityProtocol =
                SecurityProtocolType.Tls12 | SecurityProtocolType.Tls11;

            var request = (HttpWebRequest)WebRequest.Create(
                "https://traces-app.tdscpc.gov.in/loginservice/api/auth/generateCaptcha");

            request.Method = "GET";
            request.Accept = "application/json";
            request.UserAgent = "Mozilla/5.0";
            request.CookieContainer = TracesSession.CookieJar;
            request.KeepAlive = true;

            var response = (HttpWebResponse)request.GetResponse();

            if (response.Cookies != null)
                TracesSession.CookieJar.Add(response.Cookies);

            string json;
            using (var reader = new StreamReader(response.GetResponseStream()))
            {
                json = reader.ReadToEnd();
            }

            dynamic obj = Newtonsoft.Json.JsonConvert.DeserializeObject(json);

            string base64 = obj.image;
            string captchaId = obj.id;

            byte[] bytes = Convert.FromBase64String(base64);

            Image img;
            using (var ms = new MemoryStream(bytes))
            {
                img = Image.FromStream(ms);
            }

            return new CaptchaResult
            {
                CaptchaImage = img,
                CaptchaId = captchaId
            };
        }

