        private void WarmUpTLS()
        {
            try
            {
                HttpWebRequest warmupRequest = (HttpWebRequest)WebRequest.Create("https://www.tdscpc.gov.in/app/login.xhtml");
                warmupRequest.Method = "GET";
                warmupRequest.KeepAlive = false;
                warmupRequest.Timeout = 20000;
                warmupRequest.ReadWriteTimeout = 20000;
                warmupRequest.UserAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64)";
                warmupRequest.Accept = "*/*";

                using (HttpWebResponse response = (HttpWebResponse)warmupRequest.GetResponse())
                {
                    if (response.StatusCode == HttpStatusCode.OK)
                    {
                        // TLS session is now warmed up
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Warm-up failed: " + ex.Message);
            }
        }

