        public string SubmitProteanRequest(string tan, string prn, string captcha)
        {
            try
            {
                string postUrl = "https://onlineservices.tin.egov.proteantech.in/TIN/UnAuthorizedView.do";

                var postData = new Dictionary<string, string>
    {
        { "TAN", tan },
        { "PRN", prn },
        { "captchaText", captcha },
        { "captch_String", "" },
        { "count", "5" },
        { "CaptchaValidate", "CaptchaValidateflag" }
    };

                var content = new FormUrlEncodedContent(postData);

                var response = _client.PostAsync(postUrl, content).Result;

                return response.Content.ReadAsStringAsync().Result;
            }
            catch (Exception ex)
            {
                return "";
                //cmnService.J_UserMessage(ex.Message);
                //MessageBox.Show
            }
        }


