                            //{
                            //    dRow = dTable.NewRow();
                            //    dRow[j] = Convert.ToString(cols[j].InnerText); //.Replace("\t", "").Replace("\t", "").Replace("\n", "");
                            //    dTable.Rows.Add(dRow);
