        #region ChallanStatusQueryInBulk

        public List<ChallanQuery> ChallanStatusQueryInBulk(
            List<ChallanQuery> objData,
            string strCaptchaCode)
        {
            List<ChallanQuery> listResult =
                new List<ChallanQuery>();

            try
            {
                if (objData == null || objData.Count == 0)
                    return listResult;

                // ============================================================
                // PROCESS EACH CHALLAN
                // ============================================================

                foreach (ChallanQuery dataVal in objData)
                {
                    try
                    {
                        // ----------------------------------------------------
                        // CREATE TRACES DATA
                        // ----------------------------------------------------

                        TracesData objTracesData =
                            new TracesData();

                        objTracesData.BSRCode =
                            Convert.ToString(dataVal.BSRCode).Trim();

                        objTracesData.TaxDepositedDate =
                            String.Format(
                                "{0:dd-MMM-yyyy}",
                                Convert.ToDateTime(dataVal.ChallanDate));

                        objTracesData.ChallanSerialNo =
                            Convert.ToString(dataVal.ChallanNo).Trim();

                        objTracesData.ChallanAmount =
                            Convert.ToString(dataVal.ChallanAmount).Trim();

                        if (objTracesData.ChallanAmount == "0.0000")
                            objTracesData.ChallanAmount = "0";

                        // ====================================================
                        // STEP 1 : GET CHALLAN DETAILS FROM CURRENT TRACES
                        // ====================================================

                        TracesResponse objResponse =
                            CIN_CIN_BINParticulars_New(objTracesData);

                        // ----------------------------------------------------
                        // CHECK RESPONSE
                        // ----------------------------------------------------

                        if (objResponse == null)
                        {
                            dataVal.Message =
                                enmChallanStatus.RECORD_NOT_FOUND;

                            dataVal.ErrorMessage =
                                "Unable to get Challan details.";

                            listResult.Add(dataVal);

                            continue;
                        }

                        if (objResponse.Respons ==
                            enmResponse.SessionTimeout)
                        {
                            dataVal.Message =
                                enmChallanStatus.PROCESSING_FAILED;

                            dataVal.ErrorMessage =
                                "TRACES session expired.";

                            listResult.Add(dataVal);

                            continue;
                        }

                        if (objResponse.Respons ==
                            enmResponse.Failed)
                        {
                            dataVal.Message =
                                enmChallanStatus.PROCESSING_FAILED;

                            dataVal.ErrorMessage =
                                objResponse.Message;

                            listResult.Add(dataVal);

                            continue;
                        }

                        // ====================================================
                        // STEP 2 : GET CIN DATA TABLE
                        // ====================================================

                        DataTable dTable =
                            objResponse.CustomeTypes as DataTable;

                        if (dTable == null ||
                            dTable.Rows.Count == 0)
                        {
                            dataVal.Message =
                                enmChallanStatus.RECORD_NOT_FOUND;

                            dataVal.ErrorMessage =
                                "Challan details not found.";

                            listResult.Add(dataVal);

                            continue;
                        }

                        // ====================================================
                        // STEP 3 : GET RECEIPT NUMBER
                        // ====================================================

                        string strReceiptNumber = "";

                        if (dTable.Columns.Contains("Recipt Number"))
                        {
                            strReceiptNumber =
                                Convert.ToString(
                                    dTable.Rows[0]["Recipt Number"]).Trim();
                        }

                        if (String.IsNullOrEmpty(strReceiptNumber))
                        {
                            dataVal.Message =
                                enmChallanStatus.RECORD_NOT_FOUND;

                            dataVal.ErrorMessage =
                                "Receipt Number not found.";

                            listResult.Add(dataVal);

                            continue;
                        }

                        dataVal.ReceiptNumber =
                            strReceiptNumber;

                        // ====================================================
                        // STEP 4 : REQUEST CONSUMPTION DETAILS
                        // ====================================================

                        TracesData objConsumption =
                            new TracesData();

                        objConsumption.BSRCode =
                            Convert.ToString(dataVal.BSRCode).Trim();

                        objConsumption.FromChallanDepositDate =
                            String.Format(
                                "{0:dd-MMM-yyyy}",
                                Convert.ToDateTime(dataVal.ChallanDate));

                        objConsumption.ChallanSerialNo =
                            Convert.ToString(dataVal.ChallanNo).Trim();

                        objConsumption.ChallanAmount =
                            String.Format(
                                "{0:0.00}",
                                Convert.ToDouble(
                                    dataVal.ChallanAmount));

                        objConsumption.PRN_NO =
                            dataVal.ReceiptNumber;

                        // ----------------------------------------------------
                        // CALL CONSUMPTION DETAILS
                        // ----------------------------------------------------

                        TracesResponse objConsumptionResponse =
                            RequestForConsumptionDetailsCIN(
                                objConsumption);

                        if (objConsumptionResponse == null)
                        {
                            dataVal.Message =
                                enmChallanStatus.PROCESSING_FAILED;

                            dataVal.ErrorMessage =
                                "Unable to get consumption details.";

                            listResult.Add(dataVal);

                            continue;
                        }

                        if (objConsumptionResponse.Respons ==
                            enmResponse.Failed)
                        {
                            dataVal.Message =
                                enmChallanStatus.PROCESSING_FAILED;

                            dataVal.ErrorMessage =
                                objConsumptionResponse.Message;

                            listResult.Add(dataVal);

                            continue;
                        }

                        // ====================================================
                        // STEP 5 : GET AVAILABLE BALANCE
                        // ====================================================

                        DataTable dTableConsumption =
                            objConsumptionResponse.CustomeTypes as DataTable;

                        double dblAvailableAmount = 0;

                        if (dTableConsumption != null)
                        {
                            if (dTableConsumption.Rows.Count > 1)
                            {
                                foreach (DataRow row
                                    in dTableConsumption.Rows)
                                {
                                    if (dTableConsumption.Columns.Contains(
                                            "Available Amount"))
                                    {
                                        string strAvailable =
                                            Convert.ToString(
                                                row["Available Amount"]).Trim();

                                        if (!String.IsNullOrEmpty(
                                            strAvailable))
                                        {
                                            double dblValue;

                                            if (Double.TryParse(
                                                strAvailable,
                                                out dblValue))
                                            {
                                                dblAvailableAmount +=
                                                    dblValue;
                                            }
                                        }
                                    }
                                }
                            }
                            else if (dTableConsumption.Rows.Count == 1)
                            {
                                if (dTableConsumption.Columns.Contains(
                                        "Available Amount"))
                                {
                                    string strAvailable =
                                        Convert.ToString(
                                            dTableConsumption.Rows[0]
                                            ["Available Amount"]).Trim();

                                    if (!String.IsNullOrEmpty(strAvailable))
                                    {
                                        Double.TryParse(
                                            strAvailable,
                                            out dblAvailableAmount);
                                    }
                                }
                            }
                            else
                            {
                                dblAvailableAmount =
                                    Convert.ToDouble(
                                        dataVal.ChallanAmount);
                            }
                        }
                        else
                        {
                            dblAvailableAmount =
                                Convert.ToDouble(
                                    dataVal.ChallanAmount);
                        }

                        // ====================================================
                        // STEP 6 : STORE AVAILABLE AMOUNT
                        // ====================================================

                        dataVal.AvailableAmount =
                            String.Format(
                                "{0:0.00}",
                                dblAvailableAmount);

                        // ====================================================
                        // STEP 7 : SET CHALLAN STATUS
                        // ====================================================

                        dataVal.Message =
                            enmChallanStatus.AMOUNT_MATCHED;

                        dataVal.ErrorMessage = "";

                        listResult.Add(dataVal);
                    }
                    catch (Exception exChallan)
                    {
                        // ----------------------------------------------------
                        // DON'T STOP OTHER CHALLANS
                        // ----------------------------------------------------

                        dataVal.Message =
                            enmChallanStatus.PROCESSING_FAILED;

                        dataVal.ErrorMessage =
                            exChallan.Message;

                        listResult.Add(dataVal);
                    }
                }

                return listResult;
            }
            catch (Exception err)
            {
                throw;
            }
        }

        #endregion

