                }


                //CAPTCHA CODE VALIDATION
                if (Regex.IsMatch(strResponse, "Text does not match. Please enter new text.", RegexOptions.IgnoreCase))
                {
                    List<ChallanQuery> listErr = new List<ChallanQuery>();

                    ChallanQuery chlm = new ChallanQuery();
                    chlm.Message = enmChallanStatus.WRONG_CAPTCHA;

                    listErr.Add(chlm);

                    return listErr;
                }

                if (Regex.IsMatch(strResponse, "SITE UNDER MAINTENANCE", RegexOptions.IgnoreCase))
                {
                    List<ChallanQuery> listErr = new List<ChallanQuery>();

                    ChallanQuery chlm = new ChallanQuery();
                    chlm.Message = enmChallanStatus.SERVER_MAINTENANCE_ERROR;

                    listErr.Add(chlm);

                    return listErr;
                }

                //IF NO RECORDS FOUND
                if (Regex.IsMatch(strResponse, "Record Not Found", RegexOptions.IgnoreCase))
                {
                    List<ChallanQuery> listErr = new List<ChallanQuery>();

                    ChallanQuery chlm = new ChallanQuery();
                    chlm.Message = enmChallanStatus.RECORD_NOT_FOUND;

                    listErr.Add(chlm);
                    return listErr;
                }
                //--------------------------------------------

                DataTable objTable = new DataTable();
                objTable.Columns.Add("ReceiptNumber");
                objTable.Columns.Add("DDOSerialNo");
                objTable.Columns.Add("Date");
                //--------------------------------------

                ProcessHtmlData(strResponse, ref objTable);

                //----------------------------------------------------------------------------------------------------
                Dictionary<string, string> objNameval = TraceViewStateData(strResponse, "//form[@name=\"tBAFBINAmtFormUnauth\"]");

                // List<ChallanQuery> objChlQuery = new List<ChallanQuery>();
                //----------------------------------------------------------------------------------------------------
                sbParameter = new StringBuilder();
                int intCount = 0;
                bool bnlIsRecordExists = false;

                //CHECKING IF RECORD EXISTS ON SELECTED DATE
                if (objNameval.ContainsKey("noOfObj"))
                {
                    // intCount = Convert.ToInt32(objNameval["noOfObj"]);

                    foreach (DataRow dRow in objTable.Rows)
                    {
                        foreach (ChallanQuery dataVal in objData)
                        {
                            string strChallanDate = dataVal.ChallanDate.Substring(0, 2) + "/" + dataVal.ChallanDate.Substring(3, 2) + "/" + dataVal.ChallanDate.Substring(6, 4);


                            if (Convert.ToString(dRow["Date"]).Trim() == strChallanDate &&
                                Convert.ToInt32(dRow["ReceiptNumber"]) == Convert.ToInt32(dataVal.BSRCode == "" ? "0" : dataVal.BSRCode) &&
                                Convert.ToInt32(dRow["DDOSerialNo"]) == Convert.ToInt32(dataVal.ChallanNo == "" ? "0" : dataVal.ChallanNo))
                            {
                                bnlIsRecordExists = true;
                                objNameval.Add("amt" + intCount, dataVal.ChallanAmount);
                                objNameval.Add("chk" + intCount, "on");
                                dataVal.AmountID = "amt" + intCount;

                            }
                        }
                        intCount++;
                    }
                }

                //------------------------------------------------------------------------------------------------
                if (!bnlIsRecordExists)
                {
                    // Status = enmChallanStatus.RECORD_NOT_FOUND;
                    return null;
                }
                //ADD PARAMETER TO NEXT REQUEST
                foreach (KeyValuePair<string, string> pair in objNameval)
                    sbParameter.Append(pair.Key + "=" + pair.Value + "&");
                //------------------------------------------------------------------------------------------------
                // sbParameter.Append("submit=Confirm Amount");
                //strResponse = makeHTTPPostRequest("https://onlineservices.tin.egov-nsdl.com/TIN/tBAFBINDTLSAmtVerifierUnauth.do", sbParameter);
                strResponse = makeHTTPPostRequest("https://onlineservices.tin.egov.proteantech.in/TIN/tBAFBINDTLSAmtVerifierUnauth.do", sbParameter); //-- 2025/10/08
                //-------------------------------------------------------------------------------------------------
                //ADD STATUS OF RETURING OBJECT

                foreach (ChallanQuery dataVal in objData)
                {
                    if (dataVal.AmountID != "")
                    {
                        Status = getInnerText(strResponse, "//tr[td/input[@name=\"" + dataVal.AmountID + "\"]]/td[10]");

                        if (Status == enmChallanStatus.AMOUNT_MATCHED)
                            dataVal.Message = enmChallanStatus.AMOUNT_MATCHED;
                        else if (Status == enmChallanStatus.AMOUNT_NOT_MATCHED)
                            dataVal.Message = enmChallanStatus.AMOUNT_NOT_MATCHED;
                        else
                            dataVal.Message = enmChallanStatus.RECORD_NOT_FOUND;
                    }


                }

                return objData;
            }
            catch (Exception err)
            {
                throw err;
            }

        }
        #endregion

        #region ProcessHtmlData

        private void ProcessHtmlData(string strHTML, ref DataTable dTable)
        {

            DataRow dRow = null;
            HtmlAgilityPack.HtmlDocument doc = new HtmlAgilityPack.HtmlDocument();

            doc.LoadHtml(strHTML);

            HtmlNodeCollection tables = doc.DocumentNode.SelectNodes("//table");
            if (tables != null)
            {
                HtmlNodeCollection rows = tables[0].SelectNodes(".//tr[@class='tabledetails']");
                for (int i = 0; i < rows.Count; ++i)
                {
                    HtmlNodeCollection cols = rows[i].SelectNodes(".//td");
                    if (cols != null)
                    {
                        dRow = dTable.NewRow();
                        // dRow["FA Year Code"] = strFACode;
                        // dRow["Quarter Code"] = QtrCode;
                        // dRow["FA Year"] = strFAYear;
                        dRow["ReceiptNumber"] = Convert.ToString(cols[3].InnerText).Replace("\t", "").Replace("\t", "").Replace("\n", "");
                        dRow["DDOSerialNo"] = Convert.ToString(cols[4].InnerText).Replace("\t", "").Replace("\t", "").Replace("\n", "");
                        dRow["Date"] = Convert.ToString(cols[5].InnerText).Replace("\t", "").Replace("\t", "").Replace("\n", "");

                        dTable.Rows.Add(dRow);
                    }
                }
            }
            ///return dTable;
        }
        #endregion


        #region GetChallanDetails
        //-- 2017/01/19
        public TracesResponse GetChallanDetails(ChallanQuery objData, string strCaptchaCode)
        {

            TracesResponse objRes = new TracesResponse();


            try
            {

                string strResponse = "";
                objRes.Respons = enmResponse.Success;

                //STEP 1. TO PASSING PARAMETER TO OPEN SEARCH PAGE               

                StringBuilder sbParameter = new StringBuilder();

                //FETCHING HIDDEN FIELD VALUES FOR NEXT SUBMISSION TO SERVER 
                //------------------------------------------------------------------------------------------------------------------
                //sbParameter = new StringBuilder();

                sbParameter.Append("TAN_NO=" + objData.TAN.ToString());

                sbParameter.Append("&TAN_FROM_DT_DD=" + objData.FromDate.Substring(0, 2));
                sbParameter.Append("&TAN_FROM_DT_MM=" + objData.FromDate.Substring(3, 2));
                sbParameter.Append("&TAN_FROM_DT_YY=" + objData.FromDate.Substring(6, 4));

                sbParameter.Append("&TAN_TO_DT_DD=" + objData.ToDate.Substring(0, 2));
                sbParameter.Append("&TAN_TO_DT_MM=" + objData.ToDate.Substring(3, 2));
                sbParameter.Append("&TAN_TO_DT_YY=" + objData.ToDate.Substring(6, 4));

                sbParameter.Append("&HID_IMG_TXT=" + strCaptchaCode);

                sbParameter.Append("&HIDDEN_TAN_FROM_DT_DD=01");
                sbParameter.Append("&HIDDEN_TAN_FROM_DT_MM=04");
                sbParameter.Append("&HIDDEN_TAN_TO_DT_DD=31");
                sbParameter.Append("&HIDDEN_TAN_TO_DT_MM=03");
                sbParameter.Append("&HIDDEN_TAN_TO_DT_YY=");

                sbParameter.Append("&submit=View Challan details");
                sbParameter.Append("&appUser=T");
                sbParameter.Append("&appUser=T");

                //------------------------------------------------------------------------------------------------------------------
                //STEP 2. PASSING DATE RANGE & TAN WITH OTHER HIDDEN FIELD VALUES 

                strResponse = makeHTTPPostRequest("https://tin.tin.nsdl.com/oltas/servlet/TanSearch", sbParameter);
                //----------------------------------------------------------------------------------------------------
                //CAPTCHA CODE VALIDATION
                if (Regex.IsMatch(strResponse, "Error - Text does not match. Please enter new text.", RegexOptions.IgnoreCase))
                {
                    objRes.Respons = enmResponse.Failed;
                    objRes.Message = "Invalid Captcha Code";
                    return objRes;
                }

                if (Regex.IsMatch(strResponse, "SITE UNDER MAINTENANCE", RegexOptions.IgnoreCase))
                {
                    objRes.Respons = enmResponse.Failed;
                    objRes.Message = "Server Error";
                    return objRes;
                }

                //IF NO RECORDS FOUND
                if (Regex.IsMatch(strResponse, "Record Not Found", RegexOptions.IgnoreCase))
                {
                    objRes.Respons = enmResponse.Failed;
                    objRes.Message = "Record Not Found";
                    return objRes;
                }

                //----------------------------------------------------------------------------------------------------

                //------------------------------------------------------------------------------------------------
                DataTable dTable = new DataTable();
                dTable.Columns.Add("No");
                dTable.Columns.Add("ChallanTenderDate");
                dTable.Columns.Add("ChallanSerialNo");
                dTable.Columns.Add("ReceivedData");
                dTable.Columns.Add("MajorHeadcode");
                dTable.Columns.Add("MinorHeadCode");
                dTable.Columns.Add("NatureofPayment");

                //------------------------------------------------------------------------------------------------
                DataRow dRow = null;
                HtmlAgilityPack.HtmlDocument doc = new HtmlAgilityPack.HtmlDocument();

                doc.LoadHtml(strResponse);

                HtmlNodeCollection tables = doc.DocumentNode.SelectNodes("//table[1]");
                if (tables != null)
                {
                    HtmlNodeCollection rows = tables[0].SelectNodes(".//tr");
                    for (int i = 1; i < rows.Count; ++i)
                    {
                        HtmlNodeCollection cols = rows[i].SelectNodes(".//td");
                        if (cols != null && cols.Count > 5)
                        {
                            dRow = dTable.NewRow();
                            dRow["No"] = Convert.ToString(cols[0].InnerText).Replace("\t", "").Replace("\t", "").Replace("\n", "");
                            dRow["ChallanTenderDate"] = Convert.ToString(cols[1].InnerText).Replace("\t", "").Replace("\t", "").Replace("\n", "");
                            dRow["ChallanSerialNo"] = Convert.ToString(cols[2].InnerText).Replace("\t", "").Replace("\t", "").Replace("\n", "");
                            dRow["ReceivedData"] = Convert.ToString(cols[3].InnerText).Replace("\t", "").Replace("\t", "").Replace("\n", "");
                            dRow["MajorHeadcode"] = Convert.ToString(cols[4].InnerText).Replace("\t", "").Replace("\t", "").Replace("\n", "");
                            dRow["MinorHeadCode"] = Convert.ToString(cols[5].InnerText).Replace("\t", "").Replace("\t", "").Replace("\n", "");
                            dRow["NatureofPayment"] = Convert.ToString(cols[6].InnerText).Replace("\t", "").Replace("\t", "").Replace("\n", "");

                            dTable.Rows.Add(dRow);
                        }
                    }
                }

                objRes.CustomeTypes = dTable;
                //   return objData;
            }
            catch (Exception err)
            {
                objRes.Respons = enmResponse.Failed;
                objRes.Message = "Processing of challan request failed";
                // throw err;
            }



            return objRes;


        }
