            sbParameter.Append("&page=1");
            sbParameter.Append("&sidx=");
            sbParameter.Append("&sord=asc");
            //-----------------------------
            strServerResponse = makeHTTPPostRequest(strBaseURL + "cor/srv/CorrDwnldServlet?reqtype=0", sbParameter);

            //------------------------------------------------
            //PROCESSING JSON DATA & PUT INTO DATATABLE
            //------------------------------------------------
            if (!string.IsNullOrEmpty(strServerResponse))
            {
                table = new DataTable();
                table.Columns.Add("Request Date");
                table.Columns.Add("Request Number");
                table.Columns.Add("Finnancial Year");
                table.Columns.Add("Quarter");
                table.Columns.Add("Form Type");
                table.Columns.Add("Latest Token Number");
                table.Columns.Add("Status");
                table.Columns.Add("Correction Category");
                table.Columns.Add("Remarks");
                table.Columns.Add("New Token Number");
                table.Columns.Add("Assigned To");
                table.Columns.Add("Processed Date");
                table.Columns.Add("Download");
                table.Columns.Add("Upload");
                table.Columns.Add("dwnldid");

                string strLastToken = "Test";
                DataRow dRow = null;
                double dblAmt = 0;
                // DataColumn column1
                //--------------------------------------------------------------------------
                using (JsonTextReader reader = new JsonTextReader(new StringReader(strServerResponse)))
                {
                    while (reader.Read())
                    {
                        switch (reader.TokenType)
                        {
                            case JsonToken.StartObject:
                                // Console.Write("Start object: ");
                                break;
                            case JsonToken.StartArray:
                                // Console.Write("Start array: ");
                                break;
                            case JsonToken.PropertyName:
                                //Console.WriteLine(reader.Value.ToString());

                                strLastToken = reader.Value.ToString();
                                break;
                            case JsonToken.EndArray:
                                // Console.WriteLine("End array");
                                break;
                            case JsonToken.EndObject:
                                // Console.WriteLine("End object");
                                break;
                            case JsonToken.String:
                            case JsonToken.Integer:
                            case JsonToken.Null:
                            case JsonToken.Float:
                                //------------------------------------------------------
                                switch (strLastToken)
                                {
                                    case "reqDate":
                                        dRow = table.NewRow();
                                        dRow["Request Date"] = reader.Value.ToString();
                                        break;
                                    case "reqNo":
                                        dRow["Request Number"] = reader.Value.ToString();
                                        break;
                                    case "finYr":
                                        dRow["Finnancial Year"] = reader.Value.ToString();
                                        break;

                                    case "qrtr":
                                        dRow["Quarter"] = reader.Value.ToString();
                                        break;
                                    case "frmType":
                                        dRow["Form Type"] = reader.Value.ToString();
                                        break;
                                    case "ltokenno":
                                        dRow["Latest Token Number"] = reader.Value.ToString();
                                        //   table.Rows.Add(dRow);
                                        break;
                                    case "status":
                                        dRow["Status"] = reader.Value.ToString();
                                        //   table.Rows.Add(dRow);
                                        break;
                                    case "type":
                                        dRow["Correction Category"] = reader.Value.ToString();
                                        //  table.Rows.Add(dRow);
                                        break;

                                    case "recptNum":
                                        dRow["Remarks"] = reader.Value.ToString();
                                        //  table.Rows.Add(dRow);
                                        break;

                                    case "ntokenno":
                                        dRow["New Token Number"] = reader.Value.ToString();
                                        //  table.Rows.Add(dRow);
                                        break;

                                    case "assign":
                                        dRow["Assigned To"] = reader.Value.ToString();
                                        // table.Rows.Add(dRow);
                                        break;
                                    case "prsdDate":
                                        dRow["Processed Date"] = reader.Value.ToString();
                                        //table.Rows.Add(dRow);
                                        break;

                                    case "dwnload":
                                        dRow["Download"] = reader.Value.ToString();
                                        //table.Rows.Add(dRow);
                                        break;

                                    case "upload":
                                        dRow["Upload"] = reader.Value.ToString();
                                        //table.Rows.Add(dRow);
                                        break;

                                    case "dwnldid":
                                        dRow["dwnldid"] = reader.Value.ToString();
                                        table.Rows.Add(dRow);
                                        break;

                                        /* case "chlnAmt":
                                             if (!string.IsNullOrEmpty(reader.Value.ToString()))
                                             {
                                                 dblAmt = Convert.ToDouble(reader.Value.ToString());
                                                 dRow["chllan Amount"] = String.Format("{0:0.00}", dblAmt);
                                             }
                                             else
                                             {
                                                 dRow["chllan Amount"] = "";
                                             }
                                             break;*/
                                }
                                break;
                        }
                    }
                }
            }
            else
            {
                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = "Server error";
            }
            //-----------------------------------------------
            objResponse.Respons = enmResponse.Success;
            objResponse.CustomeTypes = table;

            return objResponse;
        }

