        #region AddChallanToList

        public TracesResponse AddChallanToList(string strParam)
        {
            TracesResponse objRep = new TracesResponse();
            objRep.Respons = enmResponse.Success;
            try
            {
                strServerResponse = makeHTTPPostRequest(strBaseURL + "cor/srv/AddChallanServlet?" + strParam, new StringBuilder());
                objRep.CustomeTypes = getAddedChallanList();

                //-------------------------------------------------------------------------
                strServerResponse = makeHTTPGetRequest(strBaseURL + "ded/addchallan.xhtml");


                objParam.Clear();
                Dictionary<string, string> objNameval = TraceViewStateData(strServerResponse, "//form[@id=\"corrnActn\"]");

                objParam.Append("j_id834593793_7d61b6c5=Submit Correction Statement");
                foreach (KeyValuePair<string, string> pair in objNameval)
                {
                    //if (pair.Key != "corrnActn_SUBMIT")
                    objParam.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
                }
                //-------------------------------------------------------------------------

            }
            catch
            {
                objRep.Respons = enmResponse.Failed;
            }


            return objRep;
        }

