        #region RequestSubmitCorrection
        public TracesResponse RequestSubmitCorrection()
        {
            //--------------------------------------------------
            TracesResponse objResponse = new TracesResponse();
            objResponse.Respons = enmResponse.Success;
            //------------------------------------------------

            StringBuilder sbParameter = new StringBuilder();

            strServerResponse = makeHTTPPostRequest(strBaseURL + "ded/addchallan.xhtml", objParam);

            if (!IsStringExists(strServerResponse, "//form[@id=\"submitLinks\"]"))
            {
                this.bnlSessionExists = false;
                objResponse.Message = "Server Error";
                objResponse.Respons = enmResponse.SessionTimeout;
                return objResponse;
            }

            Dictionary<string, string> objNameval = TraceViewStateData(strServerResponse, "//form[@id=\"submitLinks\"]");
            //CHECKING ANY ERROR
            sbParameter = new StringBuilder();
            //----------------------------------------------------------
            sbParameter.Append("j_id823565703_1_5be56de4=" + HttpUtility.UrlEncode("Confirm"));
            //sbParameter.Append("&redirect=" + HttpUtility.UrlEncode("Proceed with Transaction"));

            foreach (KeyValuePair<string, string> pair in objNameval)
            {
                // if (pair.Key == "javax.faces.ViewState")
                sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
            }
            //-------------------------------------------------------------------------------------------------
            strServerResponse = makeHTTPPostRequest(strBaseURL + "ded/actionsummary.xhtml", sbParameter);

            if (!IsStringExists(strServerResponse, "//div[@id=\"content\"]"))
            {
                this.bnlSessionExists = false;
                objResponse.Message = "Server Error";
                objResponse.Respons = enmResponse.SessionTimeout;
                return objResponse;
            }
            else
            {
                objResponse.Message = "Correction statement has been submitted and will be available in Corrections Ready For Submission Page";
                objResponse.Respons = enmResponse.SessionTimeout;

            }

            return objResponse;
        }

        #endregion



        #region RequestSubmitCorrection
        public TracesResponse RequestFinalSubmission(ArrayList listData)
        {
            //--------------------------------------------------
            TracesResponse objResponse = new TracesResponse();
            objResponse.Respons = enmResponse.Success;
            //------------------------------------------------
            string strRespo = makeHTTPGetRequest(strBaseURL + "dea/correadysub.xhtml");
            //----------------------------------------------------------
            if (!IsStringExists(strServerResponse, "//form[@id=\"substmt\"]"))
            {
                this.bnlSessionExists = false;
                objResponse.Message = "Server Error";
                objResponse.Respons = enmResponse.SessionTimeout;
                return objResponse;
            }
            //---------------------------------------------------------
            StringBuilder sbParameter = new StringBuilder();

            sbParameter.Append("_search=false");
            sbParameter.Append("&rows=2000");
            // sbParameter.Append("&nd=1528177614725");
            sbParameter.Append("&page=1");
            sbParameter.Append("&sidx=");
            sbParameter.Append("&sord=asc");
            //-----------------------------
            string json = makeHTTPPostRequest(strBaseURL + "cor/srv/CorxnServlt?reqtype=0&status=RDYSUB", sbParameter);
            DataTable dTable = getProcessData(json);

            var results = dTable.AsEnumerable()
                .Where(r => r.Field<String>("finyr").Contains(Convert.ToString(listData[1]))
                   && r.Field<String>("quar").Contains(Convert.ToString(listData[2]))
                   && r.Field<String>("frmtp").Contains(Convert.ToString(listData[3]))).FirstOrDefault();

            //----------------------------------------------------------
            Dictionary<string, string> objNameval = TraceViewStateData(strRespo, "//form[@id=\"substmt\"]");
            sbParameter = new StringBuilder();
            //----------------------------------------------------------
            sbParameter.Append("view=" + HttpUtility.UrlEncode("View Statement"));
            sbParameter.Append("&corrid=" + HttpUtility.UrlEncode(Convert.ToString(results["corrid"])));
            sbParameter.Append("&stmtid=" + HttpUtility.UrlEncode(Convert.ToString(results["stmtid"])));
            sbParameter.Append("&year=" + HttpUtility.UrlEncode(Convert.ToString(results["finyr"])));
            sbParameter.Append("&formtype=" + HttpUtility.UrlEncode(Convert.ToString(results["frmtp"])));
            sbParameter.Append("&quarter=" + HttpUtility.UrlEncode(Convert.ToString(results["quar"])));
            sbParameter.Append("&dscChk=" + HttpUtility.UrlEncode(Convert.ToString(results["dschk"])));
            sbParameter.Append("&substmt_SUBMIT=1");
            //----------------------------------------------------------
            foreach (KeyValuePair<string, string> pair in objNameval)
            {
                if (pair.Key == "javax.faces.ViewState")
                    sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
            }
            //----------------------------------------------------------
            strServerResponse = makeHTTPPostRequest(strBaseURL + "dea/correadysub.xhtml", sbParameter);
            //----------------------------------------------------------
            if (!IsStringExists(strServerResponse, "//form[@id=\"submitLinks\"]"))
            {
                this.bnlSessionExists = false;
                objResponse.Message = "Server Error";
                objResponse.Respons = enmResponse.SessionTimeout;
                return objResponse;
            }
            //----------------------------------------------------------
            objNameval = TraceViewStateData(strServerResponse, "//form[@id=\"submitLinks\"]");
            //----------------------------------------------------------
            sbParameter.Clear();
            //sbParameter.Append("submitProcess=" + HttpUtility.UrlEncode("Submit for Processing"));

            string signedData = "";
            string corr = "";
            string signData = "";
            string isDscRegd = "";
            string isDscExpired = "";
            string crrusr = "";
            string dscChk = "";
            string regPAN = "";
            string prPAN = "";
            string adChFlg = "";
            string peChFlg = "";

            string piChFlg = "";
            string ccChFlg = "";
            string spSdChFlg = "";
            string salaryFlg = "";
            string moveDedOnly = "";
            string pgchk = "";

            foreach (KeyValuePair<string, string> pair in objNameval)
            {
                if (pair.Key == "signedData")
                    signedData = pair.Value;

                if (pair.Key == "corr")
                    corr = pair.Value;

                if (pair.Key == "signData")
                    signData = pair.Value;

                if (pair.Key == "isDscRegd")
                    isDscRegd = pair.Value;

                if (pair.Key == "isDscExpired")
                    isDscExpired = pair.Value;

                if (pair.Key == "currUser")
                    crrusr = pair.Value;

                if (pair.Key == "dscChk")
                    dscChk = pair.Value;

                if (pair.Key == "tanRegPan")
                    regPAN = pair.Value;
                if (pair.Key == "pan")
                    prPAN = pair.Value;
                if (pair.Key == "adChFlag")
                    adChFlg = pair.Value;
                if (pair.Key == "peChFlag")
                    peChFlg = pair.Value;
                if (pair.Key == "piChFlag")
                    piChFlg = pair.Value;
                if (pair.Key == "ccChFlag")
                    ccChFlg = pair.Value;
                if (pair.Key == "spSdChFlag")
                    spSdChFlg = pair.Value;
                if (pair.Key == "salaryFlag")
                    salaryFlg = pair.Value;

                if (pair.Key == "ocpgchk")
                    pgchk = pair.Value;

                if (pair.Key != "dscPass")
                    sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
            }
            //----------------------------------------------------------
            json = makeHTTPPostRequest(strBaseURL + "cor/srv/CorxnServlt?reqtype=4", new StringBuilder());

            if (crrusr.Trim().ToUpper() != "Y")
            {
                //-------------------------------------------------
                int pFrom = json.IndexOf(":") + 1;
