        #region getProcessData


        private DataTable getProcessData(string strjson)
        {
            DataTable table = new DataTable();
            StringBuilder sbParameter = new StringBuilder();

            if (!string.IsNullOrEmpty(strjson))
            {

                table = new DataTable();
                table.Columns.Add("stmtid");
                table.Columns.Add("finyr");
                table.Columns.Add("quar");
                table.Columns.Add("userid");
                table.Columns.Add("dschk");
                table.Columns.Add("corrid");
                table.Columns.Add("frmtp");

                string strLastToken = "Test";
                DataRow dRow = null;
                double dblAmt = 0;
                // DataColumn column1
                //--------------------------------------------------------------------------
                using (JsonTextReader reader = new JsonTextReader(new StringReader(strServerResponse)))
                {
                    while (reader.Read())
                    {
                        switch (reader.TokenType)
                        {
                            case JsonToken.StartObject:
                                // Console.Write("Start object: ");
                                break;
                            case JsonToken.StartArray:
                                // Console.Write("Start array: ");
                                break;
                            case JsonToken.PropertyName:
                                //Console.WriteLine(reader.Value.ToString());

                                strLastToken = reader.Value.ToString();
                                break;
                            case JsonToken.EndArray:
                                // Console.WriteLine("End array");
                                break;
                            case JsonToken.EndObject:
                                // Console.WriteLine("End object");
                                break;
                            case JsonToken.String:
                            case JsonToken.Integer:
                            case JsonToken.Null:
                            case JsonToken.Float:
                                //------------------------------------------------------
                                switch (strLastToken)
                                {
                                    case "stmtid":
                                        dRow = table.NewRow();
                                        dRow["stmtid"] = reader.Value.ToString();
                                        break;
                                    case "finyr":
                                        dRow["finyr"] = reader.Value.ToString();
                                        break;
                                    case "quar":
                                        dRow["quar"] = reader.Value.ToString();
                                        break;
                                    case "userid":
                                        dRow["userid"] = reader.Value.ToString();
                                        break;

                                    case "dschk":
                                        dRow["dschk"] = reader.Value.ToString();
                                        break;

                                    case "corrid":
                                        dRow["corrid"] = reader.Value.ToString();
                                        break;

                                    case "frmtp":
                                        dRow["frmtp"] = reader.Value.ToString();
                                        table.Rows.Add(dRow);
                                        break;
                                }
                                break;
                        }
                    }
                }

                //objResponse.Respons = enmResponse.Success;
                return table;
            }

            return null;
        }
