        #region RequestForAddStatementDetails
        public TracesResponse RequestForAddStatementDetails_(NonFilling objData, out DataTable table)
        {
            string json = "";
            table = null;
            //MAKE GET REQUEST
            //--------------------------------------------------
            TracesResponse objResponse = new TracesResponse();
            objResponse.Respons = enmResponse.Success;
            //--------------------------------------------------
            try
            {
                string strResponse = makeHTTPGetRequest(strBaseURL + "ded/dclrtnaddnonfiling.xhtml");
                //-------------------------------------------------- 
                //CHECKING ANY ERROR FROM SERVER POINT
                if (!IsStringExists(strServerResponse, "//form[@id=\"nonFiling\"]"))
                {
                    objResponse.Message = "Server Error";
                    objResponse.Respons = enmResponse.SessionTimeout;
                    return objResponse;
                }
                //--------------------------------------------------------------------
                StringBuilder objParam = new StringBuilder();
                objParam.Append("_search=false");
                objParam.Append("&rows=100");
                objParam.Append("&page=1");
                objParam.Append("&sidx=");
                objParam.Append("&sord=asc");
                //--------------------------------------------------
                json = makeHTTPPostRequest("https://www.tdscpc.gov.in/app/ded/srv/DclrtnNonFilingServlet?fy=" + objData.FAYear + "&qt=" + objData.Quarter + "&ft=" + objData.Forms + "&reason=" + objData.Reason + "&specReasn=" + objData.SpecifyReason + "&reqtype=3&permStatusValue=" + objData.Flag, objParam);
                //--------------------------------------------------
                //PROCESSING JSON DATA & PUT INTO DATATABLE


                if (!string.IsNullOrEmpty(json))
                {
                    table = new DataTable();
                    table.Columns.Add("Sr.No.");
                    table.Columns.Add("Finnancial Year");
                    table.Columns.Add("Quarter");
                    table.Columns.Add("Form Type");
                    table.Columns.Add("Reason");
                    table.Columns.Add("permStatus");

                    string strLastToken = "Test";
                    DataRow dRow = null;
                    // DataColumn column1
                    //--------------------------------------------------------------------------
                    using (JsonTextReader reader = new JsonTextReader(new StringReader(json)))
                    {
                        while (reader.Read())
                        {
                            switch (reader.TokenType)
                            {
                                case JsonToken.StartObject:
                                    // Console.Write("Start object: ");
                                    break;
                                case JsonToken.StartArray:
                                    // Console.Write("Start array: ");
                                    break;
                                case JsonToken.PropertyName:
                                    //Console.WriteLine(reader.Value.ToString());

                                    strLastToken = reader.Value.ToString();
                                    break;
                                case JsonToken.EndArray:
                                    // Console.WriteLine("End array");
                                    break;
                                case JsonToken.EndObject:
                                    // Console.WriteLine("End object");
                                    break;
                                case JsonToken.String:
                                case JsonToken.Integer:
                                case JsonToken.Null:
                                case JsonToken.Float:
                                    //------------------------------------------------------
                                    switch (strLastToken)
                                    {
                                        case "srNo":
                                            dRow = table.NewRow();
                                            dRow["Sr.No."] = reader.Value.ToString();
                                            break;

                                        case "permStatus":
                                            dRow["permStatus"] = reader.Value.ToString();
                                            break;

                                        case "reason":
                                            dRow["Reason"] = reader.Value.ToString();
                                            break;

                                        case "finyear":
                                            dRow["Finnancial Year"] = reader.Value.ToString();
                                            break;

                                        case "quarter":
                                            dRow["Quarter"] = reader.Value.ToString();
                                            break;

                                        case "formtype":
                                            dRow["Form Type"] = Convert.ToString(reader.Value);
                                            table.Rows.Add(dRow);
                                            break;
                                    }
                                    break;
                            }
                        }
                    }
                }
                else
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message = "This statement is already filed/declared under Declaration of Non-Filing";
                    return objResponse;
                }

                if (table.Rows.Count <= 0)
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message = "This statement is already filed/declared under Declaration of Non-Filing";
                    return objResponse;
                }

                //=======================================================
                Dictionary<string, string> objNameval = TraceViewStateData(strResponse, "//form[@id=\"stmtDetls\"]");
                //CHECKING ANY ERROR
                StringBuilder sbParameter = new StringBuilder();
                //----------------------------------------------------------
                sbParameter.Append("proceed=" + HttpUtility.UrlEncode("proceed"));
                //sbParameter.Append("&redirect=" + HttpUtility.UrlEncode("Proceed with Transaction"));

                foreach (KeyValuePair<string, string> pair in objNameval)
                {
                    // if (pair.Key == "javax.faces.ViewState")
                    sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
                }
                //-------------------------------------------------------------------------------------------------
                strResponse = makeHTTPPostRequest(strBaseURL + "ded/dclrtnaddnonfiling.xhtml", sbParameter);


                //CHECKING ANY ERROR FROM SERVER POINT
                if (!IsStringExists(strResponse, "//form[@id=\"stmtDetls\"]"))
                {
                    objResponse.Message = "Server Error";
                    objResponse.Respons = enmResponse.SessionTimeout;
                    return objResponse;
                }
                //--------------------------------------------------------------------
                sbParameter.Clear();
                sbParameter.Append("agree=" + HttpUtility.UrlEncode("I Agree"));

                objNameval.Clear();
                objNameval = TraceViewStateData(strResponse, "//form[@id=\"stmtDetls\"]");

                foreach (KeyValuePair<string, string> pair in objNameval)
                {
                    // if (pair.Key == "javax.faces.ViewState")
                    sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
                }
                //-------------------------------------------------------------------------------------------------
                strResponse = makeHTTPPostRequest(strBaseURL + "ded/dclrtnstmnts.xhtml", sbParameter);


                //CHECKING ANY ERROR FROM SERVER POINT
                if (!IsStringExists(strResponse, "//form[@id=\"deducteeDetails\"]"))
                {
                    objResponse.Message = "Server Error";
                    objResponse.Respons = enmResponse.SessionTimeout;
                    return objResponse;
                }
                //-------------------------------------------------------------------------------------------------
                sbParameter.Clear();
                objNameval.Clear();
                objNameval = TraceViewStateData(strResponse, "//form[@id=\"deducteeDetails\"]");

                sbParameter.Append("j_id1090227775_2b136635=" + HttpUtility.UrlEncode("Proceed"));
                foreach (KeyValuePair<string, string> pair in objNameval)
                {
                    // if (pair.Key == "javax.faces.ViewState")
                    sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
                }
                //-------------------------------------------------------------------------------------------------

                strResponse = makeHTTPPostRequest(strBaseURL + "ded/dclrtnprfldetls.xhtml", sbParameter);


                if (!IsStringExists(strResponse, "//form[@id=\"requestConfirm\"]"))
                {
                    objResponse.Message = "Server Error";
                    objResponse.Respons = enmResponse.SessionTimeout;
                    return objResponse;
                }
                else
                {

                    string strMsg = RetrieveElementValue(strResponse, "//form[@id=\"requestConfirm\"]", "//div[@class=\"boldFont justifyText\"]", enmElementType.InnerText);

                    objResponse.Message = strMsg;
                    objResponse.Respons = enmResponse.Success;
                }
            }
            catch (Exception err)
            {
                if (Regex.IsMatch(err.Message, "410"))
                    objResponse.Respons = enmResponse.SessionTimeout;
                else
                    objResponse.Respons = enmResponse.Failed;

                objResponse.Message = err.Message;
            }

            return objResponse;
        }

