        #region RequestForFillingStatus_New
        public TracesResponse RequestForFillingStatus_New(out DataTable table)
        {
            string json = "";
            table = null;
            //MAKE GET REQUEST
            //--------------------------------------------------
            TracesResponse objResponse = new TracesResponse();
            objResponse.Respons = enmResponse.Success;
            //--------------------------------------------------
            try
            {// ================================
                // STEP 1: INIT OLD DOMAIN COOKIE
                // ================================
                //makeHTTPGetRequest(
                //    "https://traces61.tdscpc.gov.in/",
                //    "https://traces.tdscpc.gov.in/"
                //);

                // ================================
                // STEP 2: SESSION BRIDGE
                // ================================
                makeHTTPGetRequest(
                    strBaseURL + "preauthV2.xhtml",
                    "https://traces.tdscpc.gov.in/"
                );

                // ================================
                // STEP 3: OPEN PAGE
                // ================================
                makeHTTPGetRequest(
                    strBaseURL + "ded/dclrtnaddnonfiling.xhtml",
                    strBaseURL + "preauthV2.xhtml"
                );
                strServerResponse = makeHTTPGetRequest(strBaseURL + "ded/dclrtnaddnonfiling.xhtml");
                //-------------------------------------------------- 
                //CHECKING ANY ERROR FROM SERVER POINT
                if (!IsStringExists(strServerResponse, "//form[@id=\"nonFiling\"]"))
                {
                    objResponse.Message = "Server Error";
                    objResponse.Respons = enmResponse.SessionTimeout;
                    return objResponse;
                }
                //--------------------------------------------------------------------
                StringBuilder objParam = new StringBuilder();
                objParam.Append("_search=false");
                objParam.Append("&rows=100");
                objParam.Append("&page=1");
                objParam.Append("&sidx=");
                objParam.Append("&sord=asc");
                //--------------------------------------------------
                //-- ANIK 2013-07-13
                //json = makeHTTPPostRequest(strBaseURL + "DedStmtStatusServlet?financialYear=" + objData.FAYear + "&quarter=" + objData.Quarter + "&formType=" + objData.Forms, objParam);
                //string ss = strBaseURL + "ded/srv/DclrtnNonFilingServlet?fy=" + objData.FAYear + "&qt=" + objData.Quarter + "&ft=" + objData.Forms + "&reason=" + objData.Reason + "&specReasn=" + objData.SpecifyReason + "&reqType=3&permStatusValue=" + objData.Flag;

                json = makeHTTPPostRequest(strBaseURL + "ded/srv/DclrtnNonFilingServlet?reqtype=0&pCount=100", objParam);
                //--------------------------------------------------
                //PROCESSING JSON DATA & PUT INTO DATATABLE

                if (!string.IsNullOrEmpty(json))
                {
                    table = new DataTable();
                    table.Columns.Add("Finnancial Year");
                    table.Columns.Add("Quarter");
                    table.Columns.Add("Form Type");
                    table.Columns.Add("Status");
                    table.Columns.Add("Reason");
                    table.Columns.Add("Date");

                    table.Columns.Add("commId");
                    table.Columns.Add("hidfinYr");
                    table.Columns.Add("hidquat");
                    table.Columns.Add("declId");


                    string strLastToken = "Test";
                    DataRow dRow = null;
                    // DataColumn column1
                    //--------------------------------------------------------------------------
                    using (JsonTextReader reader = new JsonTextReader(new StringReader(json)))
                    {
                        while (reader.Read())
                        {
                            switch (reader.TokenType)
                            {
                                case JsonToken.StartObject:
                                    // Console.Write("Start object: ");
                                    break;
                                case JsonToken.StartArray:
                                    // Console.Write("Start array: ");
                                    break;
                                case JsonToken.PropertyName:
                                    //Console.WriteLine(reader.Value.ToString());

                                    strLastToken = reader.Value.ToString();
                                    break;
                                case JsonToken.EndArray:
                                    // Console.WriteLine("End array");
                                    break;
                                case JsonToken.EndObject:
                                    // Console.WriteLine("End object");
                                    break;
                                case JsonToken.String:
                                case JsonToken.Integer:
                                case JsonToken.Null:
                                case JsonToken.Float:
                                    //------------------------------------------------------
                                    switch (strLastToken)
                                    {
                                        case "declId":
                                            dRow = table.NewRow();
                                            dRow["declId"] = Convert.ToString(reader.Value);

                                            break;
                                        case "formType":
                                            dRow["Form Type"] = reader.Value.ToString();
                                            break;

                                        case "hidfinYr":

                                            dRow["hidfinYr"] = reader.Value.ToString();
                                            break;


                                        case "quarter":
                                            dRow["Quarter"] = reader.Value.ToString();
                                            break;

                                        case "status":
                                            dRow["Status"] = reader.Value.ToString();
                                            break;
                                        case "reason":
                                            dRow["Reason"] = reader.Value.ToString();
                                            break;
                                        case "date":
                                            //dRow["Date"] = reader.Value.ToString();
                                            if (dRow == null) dRow = table.NewRow();
                                            dRow["Date"] = reader.Value?.ToString();
                                            break;
                                        case "commId":
                                            dRow["commId"] = reader.Value.ToString();
                                            break;
                                        case "hidquat":
                                            dRow["hidquat"] = reader.Value.ToString();
                                            break;
                                        case "finYr":
                                            dRow["Finnancial Year"] = reader.Value.ToString();
                                            table.Rows.Add(dRow);
                                            break;

                                    }
                                    break;
                            }
                        }
                    }
                }
                else
                {
                    objResponse.Respons = enmResponse.Success;
                    objResponse.Message = "No Data";
                }
            }
            catch (Exception err)
            {
                if (Regex.IsMatch(err.Message, "410"))
                    objResponse.Respons = enmResponse.SessionTimeout;
                else
                    objResponse.Respons = enmResponse.Failed;

                objResponse.Message = err.Message;
            }

            return objResponse;
        }

