        #region RequestCommunicationInboxDetails
        public TracesResponse RequestCommunicationInboxDetails(string commId, string description, out string htmlResponse)
        {
            htmlResponse = "";
            TracesResponse resp = new TracesResponse();
            resp.Respons = enmResponse.Success;

            try
            {
                // Encode description exactly like browser
                string encodedDescr = HttpUtility.UrlEncode(description);

                StringBuilder param = new StringBuilder();
                param.Append("_search=false");
                param.Append("&rows=1");
                param.Append("&page=1");
                param.Append("&sidx=");
                param.Append("&sord=asc");

                string url = strBaseURL +
                    "ded/srv/CommInboxServlet?reqtype=2&commId=" + commId +
                    "&description=" + encodedDescr;

                // POST request
                htmlResponse = makeHTTPPostRequest(url, param);

                if (string.IsNullOrEmpty(htmlResponse))
                {
                    resp.Respons = enmResponse.Failed;
                    resp.Message = "Empty response";
                }
            }
            catch (Exception ex)
            {
                resp.Respons = enmResponse.Failed;
                resp.Message = ex.Message;
            }

            return resp;
        }

        public TracesResponse RequestCommunicationInboxDetails_OneLogin(
                                    string commId,
                                    string description,
                                    out string jsonResponse)
        {
            jsonResponse = "";
            TracesResponse resp = new TracesResponse();
            resp.Respons = enmResponse.Success;

            try
            {
                //-------------------------------------------------------------------
                // STEP 1: GET THE DETAIL PAGE (MUST fetch ViewState)
                //-------------------------------------------------------------------

                string urlDetailPage = strBaseURL +
                    "ded/dedinboxdetails.xhtml?commId=" + commId;

                string detailHtml = TracesConnect_OneLogin.MakeHTTPGet_OneLogin(urlDetailPage);

                if (string.IsNullOrWhiteSpace(detailHtml))
                {
                    resp.Respons = enmResponse.SessionTimeout;
                    resp.Message = "Empty TRACES response";
                    return resp;
                }

                // Extract javax.faces.ViewState
                string viewState = ExtractViewState(detailHtml);

                if (string.IsNullOrEmpty(viewState))
                {
                    resp.Respons = enmResponse.SessionTimeout;
                    resp.Message = "Unable to extract ViewState";
                    return resp;
                }

                //-------------------------------------------------------------------
                // STEP 2: PREPARE POST DATA FOR reqtype=2 (DETAIL REQUEST)
                //-------------------------------------------------------------------

                StringBuilder postData = new StringBuilder();
                postData.Append("_search=false");
                postData.Append("&rows=50");
                postData.Append("&page=1");
                postData.Append("&sidx=");
                postData.Append("&sord=asc");

                // Must send description encoded EXACTLY like browser
                string encodedDescr = HttpUtility.UrlEncode(description);

                string reqUrl = strBaseURL +
                    "ded/srv/CommInboxServlet?reqtype=2&commId=" + commId +
                    "&description=" + encodedDescr;

                // Important: send ViewState same way JSF sends it
                postData.Append("&javax.faces.ViewState=" + HttpUtility.UrlEncode(viewState));

                //-------------------------------------------------------------------
                // STEP 3: SEND POST REQUEST
                //-------------------------------------------------------------------

                jsonResponse = TracesConnect_OneLogin.MakeHTTPPost_OneLogin(
                    reqUrl,
                    postData
                );

                //-------------------------------------------------------------------
                // STEP 4: VALIDATE RESPONSE
                //-------------------------------------------------------------------

                if (string.IsNullOrWhiteSpace(jsonResponse))
                {
                    resp.Respons = enmResponse.Failed;
                    resp.Message = "No data returned";
                }
                else if (jsonResponse.TrimStart().StartsWith("<"))
                {
                    // Means TRACES returned HTML (login page)
                    resp.Respons = enmResponse.SessionTimeout;
                    resp.Message = "Session Expired - Received HTML instead of JSON";
                }

                return resp;
            }
            catch (Exception ex)
            {
                resp.Respons = enmResponse.Failed;
                resp.Message = ex.Message;
                return resp;
            }
        }

        #endregion

        #region ParseCommunicationDetails
        public DataTable ParseCommunicationDetails(string json)
        {
            DataTable dt = new DataTable();
            dt.Columns.Add("Reference No");
            dt.Columns.Add("Category");
            dt.Columns.Add("Description");
            dt.Columns.Add("Subject");
            dt.Columns.Add("Message");
            dt.Columns.Add("commid");            

            try
            {
                dynamic obj = Newtonsoft.Json.JsonConvert.DeserializeObject(json);

                if (obj.rows != null && obj.rows.Count > 0)
                {
                    var r = obj.rows[0];

                    DataRow dr = dt.NewRow();
                    dr["Reference No"] = (string)r.commRefNo;
                    dr["Category"] = (string)r.commcat;
                    dr["Description"] = (string)r.description;
                    dr["Subject"] = (string)r.subject;
                    dr["Message"] = (string)r.message;
                    dr["commid"] = (string)r.commid;

                    dt.Rows.Add(dr);
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("JSON Parse Error: " + ex.Message);
            }

            return dt;
        }
        #endregion

