        #region RequestForUnconsumedChallanList_OneLogin
        public TracesResponse RequestForUnconsumedChallanList_OneLogin(out DataTable table)
        {
            table = null;
            string json = "";
            TracesResponse objResponse = new TracesResponse();
            objResponse.Respons = enmResponse.Success;

            try
            {
                // -------------------------------------------------------------
                // STEP 1: OPEN UNCONSUMED CHALLAN PAGE (SESSION VALIDATION)
                // -------------------------------------------------------------

                string html = TracesConnect_OneLogin.MakeHTTPGet_OneLogin(
                    strBaseURL + "ded/unconschallandetail.xhtml"
                );

                // jqGrid container validation
                //if (!IsStringExists(html, "<table id=\"viewunconchlntab\""))
                if (html == null || html.IndexOf("viewunconchlntab", StringComparison.OrdinalIgnoreCase) < 0)
                {
                    objResponse.Message = "Session Timeout or Invalid TRACES Response";
                    objResponse.Respons = enmResponse.SessionTimeout;
                    return objResponse;
                }

                // -------------------------------------------------------------
                // STEP 2: FETCH jqGrid DATA
                // -------------------------------------------------------------

                StringBuilder objParam = new StringBuilder();
                objParam.Append("_search=false");
                objParam.Append("&rows=100");
                objParam.Append("&page=1");
                objParam.Append("&sidx=");
                objParam.Append("&sord=asc");

                json = TracesConnect_OneLogin.MakeHTTPPost_OneLogin(
                    strBaseURL + "ded/srv/GetUnconChlnDetailServlet?reqtype=0",
                    objParam
                );

                if (string.IsNullOrEmpty(json))
                {
                    objResponse.Message = "No Data Returned";
                    return objResponse;
                }

                JObject root = JObject.Parse(json);
                JArray rows = (JArray)root["rows"];

                if (rows == null || rows.Count == 0)
                {
                    objResponse.Message = "No Unconsumed Challans Found";
                    return objResponse;
                }

                // -------------------------------------------------------------
                // STEP 3: BUILD DATATABLE (EXACT jqGrid MAPPING)
                // -------------------------------------------------------------

                table = new DataTable();

                table.Columns.Add("BSR Code");
                table.Columns.Add("Date of Deposit");
                table.Columns.Add("Challan Serial No");
                table.Columns.Add("Challan Amount");        // hidden in UI
                table.Columns.Add("Unconsumed Amount");     // View Amount text

                // hidden / technical (needed for Phase-2)
                table.Columns.Add("Receipt No");
                table.Columns.Add("hidChallanAmount");
                table.Columns.Add("hidUnconsumedAmount");

                foreach (JObject item in rows)
                {
                    DataRow dr = table.NewRow();

                    dr["BSR Code"] = item["chlnbsrcode"]?.ToString();
                    dr["Date of Deposit"] = item["dateofdep"]?.ToString();
                    dr["Challan Serial No"] = item["chlnsrno"]?.ToString();

                    // As per UI
                    dr["Challan Amount"] = "";                 // hidden
                    dr["Unconsumed Amount"] = "View Amount";   // clickable text

                    // Preserve server values
                    dr["Receipt No"] = item["recptNo"]?.ToString();
                    dr["hidChallanAmount"] = item["hidchlnamt"]?.ToString();
                    dr["hidUnconsumedAmount"] = item["hidunconschlnamt"]?.ToString();

                    table.Rows.Add(dr);
                }

                return objResponse;
            }
            catch (Exception ex)
            {
                if (Regex.IsMatch(ex.Message, "410"))
                    objResponse.Respons = enmResponse.SessionTimeout;
                else
                    objResponse.Respons = enmResponse.Failed;

                objResponse.Message = ex.Message;
                return objResponse;
            }
        }
        #endregion

        

        #region ValidateUnconsumedChallanAmount_OneLogin
        public decimal ValidateUnconsumedChallanAmount_OneLogin(
            string receiptNo,
            string challanSerialNo,
            string enteredAmount,
            string dateOfDeposit,
            string bsrCode
        )
        {
            StringBuilder postData = new StringBuilder();

            postData.Append("recptNum=").Append(receiptNo);
            postData.Append("&chlnSNo=").Append(challanSerialNo);
            postData.Append("&enteredAmt=").Append(enteredAmount);
            postData.Append("&dateOfDep=").Append(dateOfDeposit);
            postData.Append("&bsrCode=").Append(bsrCode); // DO NOT URL-ENCODE ****

            string json = TracesConnect_OneLogin.MakeHTTPPost_OneLogin(strBaseURL +
                "/ded/srv/GetUnconChlnDetailServlet?reqtype=1",
                postData
            );

            if (string.IsNullOrWhiteSpace(json))
                throw new Exception("Empty response from TRACES");

            JArray arr = JArray.Parse(json);
            JObject obj = (JObject)arr[0];

            int success = obj["success"].Value<int>();

            switch (success)
            {
                case 2:
                    return obj["unConsChlnAmt"].Value<decimal>();

                case 1:
                    throw new Exception("Challan Amount is mandatory");

                case 3:
                    throw new Exception("Invalid Challan Amount");

                case 4:
                    throw new Exception("Amount should be entered in two decimal places");

                case 5:
                    throw new Exception("Challan Amount entered is incorrect");

                default:
                    throw new Exception("Unknown TRACES response");
            }
        }
        #endregion

        #region DownloadCertificate
        public TracesResponse DownloadCertificate(
                            string commId,
                            string finYear,
                            string formType,
                            string quarter,
                            string certNum,
                            string description,
                            out byte[] pdfBytes)
        {
            pdfBytes = null;
            var resp = new TracesResponse { Respons = enmResponse.Success };

            try
            {
                // Verify session
                if (objContainer == null || objContainer.Count == 0)
                {
                    resp.Respons = enmResponse.Failed;
                    resp.Message = "Session expired. Please login again.";
                    return resp;
                }

                // Build URL EXACTLY as the browser does
                string url = strBaseURL + "ded/srv/CommInboxServlet" +
                             "?commId=" + HttpUtility.UrlEncode(commId) +
                             "&finYear=" + HttpUtility.UrlEncode(finYear) +
                             "&formType=" + HttpUtility.UrlEncode(formType) +
                             "&reqtype=5" +
                             "&certNum=" + HttpUtility.UrlEncode(certNum) +
                             "&description=" + HttpUtility.UrlEncode(description);

                // Debug logging
                System.Diagnostics.Debug.WriteLine("=== CERTIFICATE DOWNLOAD ===");
                System.Diagnostics.Debug.WriteLine("URL: " + url);
                System.Diagnostics.Debug.WriteLine($"commId: {commId}");
                System.Diagnostics.Debug.WriteLine($"finYear: {finYear}");
                System.Diagnostics.Debug.WriteLine($"formType: {formType}");
                System.Diagnostics.Debug.WriteLine($"certNum: {certNum}");
                System.Diagnostics.Debug.WriteLine($"description: {description}");

                HttpWebRequest req = (HttpWebRequest)WebRequest.Create(url);
                req.Method = "GET";
                req.CookieContainer = objContainer;
                req.UserAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Safari/537.36";
                req.Accept = "application/pdf,*/*";
                req.Referer = strBaseURL + "ded/dedinbox.xhtml";
                req.KeepAlive = true;
                req.Headers.Add("Accept-Language", "en-US,en;q=0.9");
                req.AutomaticDecompression = DecompressionMethods.GZip | DecompressionMethods.Deflate;

                using (HttpWebResponse res = (HttpWebResponse)req.GetResponse())
                {
                    System.Diagnostics.Debug.WriteLine($"Response Status: {res.StatusCode}");
                    System.Diagnostics.Debug.WriteLine($"Content-Type: {res.ContentType}");
                    System.Diagnostics.Debug.WriteLine($"Content-Length: {res.ContentLength}");

                    string contentType = res.ContentType?.ToLower() ?? "";

                    // Check if server returned an error (HTML/Text instead of PDF)
                    if (contentType.Contains("text/html") || contentType.Contains("text/plain"))
                    {
                        using (StreamReader sr = new StreamReader(res.GetResponseStream()))
                        {
                            string errorText = sr.ReadToEnd();
                            resp.Respons = enmResponse.Failed;
                            resp.Message = "Server Error:\n" + errorText.Trim();

                            // Save error for debugging
                            File.WriteAllText(@"C:\ServerError.txt", errorText);
                            resp.Message += "\n\nFull error saved to C:\\ServerError.txt";

                            System.Diagnostics.Debug.WriteLine("Server Error: " + errorText);
                            return resp;
                        }
                    }

                    // Read the response stream
                    using (MemoryStream ms = new MemoryStream())
                    {
                        res.GetResponseStream().CopyTo(ms);
                        pdfBytes = ms.ToArray();

                        System.Diagnostics.Debug.WriteLine($"Downloaded {pdfBytes.Length} bytes");

                        // Validate PDF signature
                        if (pdfBytes.Length >= 4)
                        {
                            // Check for PDF header (%PDF)
                            if (pdfBytes[0] == 0x25 && pdfBytes[1] == 0x50 &&
                                pdfBytes[2] == 0x44 && pdfBytes[3] == 0x46)
                            {
                                System.Diagnostics.Debug.WriteLine("Valid PDF file");
                            }
                            else
                            {
                                // Not a PDF - might be error text
                                string header = System.Text.Encoding.ASCII.GetString(pdfBytes, 0, Math.Min(100, pdfBytes.Length));
                                resp.Respons = enmResponse.Failed;
                                resp.Message = $"Downloaded file is not a valid PDF.\n" +
                                               $"Size: {pdfBytes.Length} bytes\n" +
                                               $"Header: {header}";

                                File.WriteAllBytes(@"C:\InvalidFile.bin", pdfBytes);
                                resp.Message += "\n\nSaved to C:\\InvalidFile.bin for inspection";

                                pdfBytes = null;
                                return resp;
                            }
                        }
                        else
                        {
                            resp.Respons = enmResponse.Failed;
                            resp.Message = $"Downloaded file is too small: {pdfBytes.Length} bytes";
                            pdfBytes = null;
                            return resp;
                        }
                    }
                }
            }
            catch (WebException wex)
            {
                resp.Respons = enmResponse.Failed;

                if (wex.Response != null)
                {
                    HttpWebResponse errorResponse = (HttpWebResponse)wex.Response;
                    System.Diagnostics.Debug.WriteLine($"WebException Status: {errorResponse.StatusCode}");

                    using (StreamReader sr = new StreamReader(errorResponse.GetResponseStream()))
                    {
                        string errorText = sr.ReadToEnd();
                        resp.Message = $"HTTP Error {(int)errorResponse.StatusCode}: {errorResponse.StatusDescription}\n\n" +
                                       $"Server Response:\n{errorText.Trim()}";

                        File.WriteAllText(@"C:\WebError.txt", errorText);
                        resp.Message += "\n\nFull error saved to C:\\WebError.txt";

                        System.Diagnostics.Debug.WriteLine("Error Response: " + errorText);
                    }
                }
                else
                {
                    resp.Message = $"Network Error: {wex.Message}";
                }
            }
            catch (Exception ex)
            {
                resp.Respons = enmResponse.Failed;
                resp.Message = $"Exception: {ex.Message}\n\nStack Trace:\n{ex.StackTrace}";
                System.Diagnostics.Debug.WriteLine($"Exception: {ex.Message}");
            }

            return resp;
        }
        //--
        public TracesResponse DownloadCertificate_OneLogin(
                                        string commId,
                                        string finYear,
                                        string formType,
                                        string quarter,
                                        string certNum,
                                        string description,
                                        out byte[] pdfBytes)
        {
            pdfBytes = null;
            TracesResponse resp = new TracesResponse { Respons = enmResponse.Success };

            try
            {
                //-------------------------------------------------------------------
                // STEP 1: OPEN THE DETAILS PAGE TO FETCH VIEWSTATE
                //-------------------------------------------------------------------

                string urlDetail = strBaseURL +
                    "ded/dedinboxdetails.xhtml?commId=" + HttpUtility.UrlEncode(commId);

                string html = TracesConnect_OneLogin.MakeHTTPGet_OneLogin(urlDetail);

                if (string.IsNullOrWhiteSpace(html))
                {
                    resp.Respons = enmResponse.SessionTimeout;
                    resp.Message = "Session expired while loading detail page.";
                    return resp;
                }

                string viewState = ExtractViewState(html);

                if (string.IsNullOrEmpty(viewState))
                {
                    resp.Respons = enmResponse.SessionTimeout;
                    resp.Message = "Unable to extract ViewState.";
                    return resp;
                }

                //-------------------------------------------------------------------
                // STEP 2: PREPARE reqtype=5 (CERTIFICATE DOWNLOAD)
                //-------------------------------------------------------------------

                StringBuilder post = new StringBuilder();
                post.Append("javax.faces.ViewState=" + HttpUtility.UrlEncode(viewState));

                // TRACES URL for certificate download
                string url = strBaseURL +
                    "ded/srv/CommInboxServlet" +
                    "?reqtype=5" +
                    "&commId=" + HttpUtility.UrlEncode(commId) +
                    "&finYear=" + HttpUtility.UrlEncode(finYear) +
                    "&formType=" + HttpUtility.UrlEncode(formType) +
                    "&certNum=" + HttpUtility.UrlEncode(certNum) +
                    "&description=" + HttpUtility.UrlEncode(description);

                //-------------------------------------------------------------------
                // STEP 3: POST & GET PDF BYTES
                //-------------------------------------------------------------------

                byte[] rawData = TracesConnect_OneLogin.MakeHTTPPostBytes_OneLogin(url, post.ToString());


                if (rawData == null || rawData.Length < 10)
                {
                    resp.Respons = enmResponse.Failed;
                    resp.Message = "No PDF returned from TRACES.";
                    return resp;
                }

                // Validate PDF header (%PDF)
                if (rawData[0] == 0x25 && rawData[1] == 0x50 &&
                    rawData[2] == 0x44 && rawData[3] == 0x46)
                {
                    pdfBytes = rawData;
                    return resp;
                }
                else
                {
                    string header = Encoding.ASCII.GetString(rawData, 0, Math.Min(100, rawData.Length));
                    resp.Respons = enmResponse.Failed;
                    resp.Message = "Invalid PDF returned.\nHeader: " + header;
                    return resp;
                }
            }
            catch (Exception ex)
            {
                resp.Respons = enmResponse.Failed;
                resp.Message = ex.Message;
                return resp;
            }
        }

        #endregion

        #region RequestForDownloadIntimation 
        public TracesResponse RequestForDownloadIntimation(
        string commInbId,
        string finYear,
        string quarter,
        string formType,
        string commRefNo,
        string commCatgry)
        { 
            /*https://www.tdscpc.gov.in/app/ded/srv/CommInboxServlet?reqtype=3&commInbId=2430246916&finYear=2023&quarter=6&formType=24Q&commRefNo=TDS/2324/24Q/D/100053536068&commCatgry=18*/
            TracesResponse objResponse = new TracesResponse();
            //resp.Respons = enmResponse.Success;

            try
            {
                //string encodedDescr = HttpUtility.UrlEncode(description);

                string url = strBaseURL +
                             "ded/srv/CommInboxServlet?reqtype=3";

                StringBuilder param = new StringBuilder();
                param.Append("&commInbId=" + commInbId);
                param.Append("&finYear=" + finYear);
                param.Append("&quarter=" + quarter);
                param.Append("&formType=" + formType);
                param.Append("&commRefNo=" + commRefNo);
                param.Append("&commCatgry=" + commCatgry);

                string result = makeHTTPPostRequest(url, param);

                if (string.IsNullOrWhiteSpace(result))
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message = "Empty server response";
                    return objResponse;
                }

                // --------- Parse JSON array ---------
                JArray arr = JArray.Parse(result);

                if (arr.Count == 0)
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message = "Invalid server response";
                    return objResponse;
                }

                JObject obj = (JObject)arr[0];

                // CASE 1: Success  reqid PRESENT
                if (obj["reqid"] != null)
                {
                    objResponse.CustomTypes = obj["reqid"].ToString();
                    objResponse.Respons = enmResponse.Success;
                    objResponse.Message = "Request submitted successfully.\nRequest No: " + objResponse.CustomTypes;
                }
                // CASE 2: hidmsgflg PRESENT
                else if (obj["hidmsgflg"] != null)
                {
                    objResponse.Respons = enmResponse.Success;
                    objResponse.Message = "Request for Download of Intimations has already been submitted.\nNew request can be submitted only after the existing request is processed.";                        
                }
                else
                {
                    objResponse.Respons = enmResponse.Failed;
                    objResponse.Message = "Unexpected server response.";
                }
            }
            catch (Exception ex)
            {
                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = ex.Message;
            }

            return objResponse;
        }

        public TracesResponse RequestForDownloadIntimation_OneLogin(
        string commInbId,
        string finYear,
        string quarter,
        string formType,
        string commRefNo,
        string commCatgry)
        {
            TracesResponse resp = new TracesResponse { Respons = enmResponse.Success };

            try
            {
                // -------------------------------
                // STEP 1: Build TRACES request
                // -------------------------------
                string url = strBaseURL +
                             "ded/srv/CommInboxServlet?reqtype=3";

                StringBuilder post = new StringBuilder();
                post.Append("commInbId=" + HttpUtility.UrlEncode(commInbId));
                post.Append("&finYear=" + HttpUtility.UrlEncode(finYear));
                post.Append("&quarter=" + HttpUtility.UrlEncode(quarter));
                post.Append("&formType=" + HttpUtility.UrlEncode(formType));
                post.Append("&commRefNo=" + HttpUtility.UrlEncode(commRefNo));
                post.Append("&commCatgry=" + HttpUtility.UrlEncode(commCatgry));

                // -------------------------------
                // STEP 2: POST using OneLogin
                // -------------------------------
                string result = TracesConnect_OneLogin.MakeHTTPPost_OneLogin(url, post);

                if (string.IsNullOrWhiteSpace(result))
                {
                    resp.Respons = enmResponse.Failed;
                    resp.Message = "Empty server response";
                    return resp;
                }

                // -------------------------------
                // STEP 3: Parse TRACES Response
                // -------------------------------
                JArray arr = JArray.Parse(result);

                if (arr.Count == 0)
                {
                    resp.Respons = enmResponse.Failed;
                    resp.Message = "Invalid server response";
                    return resp;
                }

                JObject obj = (JObject)arr[0];

                // NEW REQUEST CREATED
                if (obj["reqid"] != null)
                {
                    resp.CustomTypes = obj["reqid"].ToString();
                    resp.Message = "Request submitted successfully.\nRequest No: " + resp.CustomTypes;
                    resp.Respons = enmResponse.Success;
                    return resp;
                }

                // REQUEST ALREADY EXISTS
                if (obj["hidmsgflg"] != null)
                {
                    resp.Respons = enmResponse.Success;
                    resp.Message =
                        "Request for Download of Intimations has already been submitted.\n" +
                        "A new request can only be submitted once the previous request is processed.";
                    return resp;
                }

                // UNEXPECTED RESPONSE
                resp.Respons = enmResponse.Failed;
                resp.Message = "Unexpected server response.";

                return resp;
            }
            catch (Exception ex)
            {
                resp.Respons = enmResponse.Failed;
                resp.Message = ex.Message;
                return resp;
            }
        }

        #endregion

