        #region RequestForKnowYouTAN

        public TracesResponse RequestForKnowYouTAN(string strTAN, string strName, string strDeductor, string strState, string strMobileNo)
        {
            TracesResponse objResponse = new TracesResponse();
            string strResponse = makeHTTPGetRequest("https://www1.incometaxindiaefiling.gov.in/e-FilingGS/Services/KnowYourTanVerify.html");
            //-------------------------------------------------- 
            //CHECKING ANY ERROR FROM SERVER POINT
            if (!IsStringExists(strServerResponse, "//form[@id=\"KnowYourTanVerify\"]"))
            {
                objResponse.Message = "Server Error";
                objResponse.Respons = enmResponse.SessionTimeout;
                // return objResponse;
            }

            Dictionary<string, string> objNameval = TraceViewStateData(strResponse, "//form[@id=\"KnowYourTanVerify\"]");
            //CHECKING ANY ERROR
            StringBuilder sbParameter = new StringBuilder();

            string searchOption = "";
            if (string.IsNullOrWhiteSpace(strTAN))
                searchOption = "name";
            else
                searchOption = "tan";

            sbParameter.Append("searchCriteria.searchOption=" + searchOption);
            sbParameter.Append("&searchCriteria.category=" + strDeductor);
            sbParameter.Append("&searchCriteria.state=" + strState);
            sbParameter.Append("&searchCriteria.name=" + strName);
            sbParameter.Append("&searchCriteria.tan=" + strTAN);
            sbParameter.Append("&mobileOfDeductee=" + strMobileNo);


            foreach (KeyValuePair<string, string> pair in objNameval)
            {
                // if (pair.Key == "javax.faces.ViewState")
                sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
            }
            //-------------------------------------------------------------------------------------------------
            strResponse = makeHTTPPostRequest("https://www1.incometaxindiaefiling.gov.in/e-FilingGS/Services/KnowYourTanVerify.html", sbParameter);

            //CHECKING ANY ERROR FROM SERVER POINT
            if (!IsStringExists(strResponse, "//form[@id=\"KnowYourTanVerifyOtp\"]"))
            {
                objResponse.Message = "Server Error";
                objResponse.Respons = enmResponse.SessionTimeout;
                // return objResponse;
            }
            else
            {
                if (Regex.IsMatch(strResponse, "Please provide the OTP sent to your Mobile Number"))
                {
                    objNameval = TraceViewStateData(strResponse, "//form[@id=\"KnowYourTanVerifyOtp\"]");
                    objResponse.Message = "Please provide the OTP sent to your Mobile Number";
                    objResponse.Respons = enmResponse.Success;

                    objResponse.CustomeTypes = objNameval;
                }
            }




            return objResponse;



        }

