        #region RequestForOTPValidation


        public TracesResponse RequestForOTPValidation(string strOTP, Dictionary<string, string> objNameval)
        {
            StringBuilder sbParameter = new StringBuilder();
            TracesResponse objResponse = new TracesResponse();

            sbParameter.Append("mobilePin=" + strOTP);
            foreach (KeyValuePair<string, string> pair in objNameval)
            {
                sbParameter.Append("&" + pair.Key + "=" + HttpUtility.UrlEncode(pair.Value));
            }

            //-------------------------------------------------------------------------------------------------
            string strResponse = makeHTTPPostRequest("https://www1.incometaxindiaefiling.gov.in/e-FilingGS/Services/KnowYourTanVerifyOtp.html", sbParameter);

            if (IsStringExists(strResponse, "//form[@id=\"KnowYourTanVerify\"]"))
            {
                if (Regex.IsMatch(strResponse, "No records found."))
                {
                    objResponse.Message = "No records found.";
                    objResponse.Respons = enmResponse.Failed;
                    return objResponse;
                }
                objResponse.Message = "No records found. Please try again";
                objResponse.Respons = enmResponse.SessionTimeout;

                return objResponse;
            }
            //-------------------------------------------------------------------------------------------
            if (Regex.IsMatch(strResponse, "Session has expired!"))
            {
                objResponse.Message = "Session has expired! Please try again";
                objResponse.Respons = enmResponse.SessionTimeout;

                return objResponse;

            }

            //-------------------------------------------------------------------------------------------
            TanDetails objDetails = new TanDetails();
            HtmlAgilityPack.HtmlDocument document = new HtmlAgilityPack.HtmlDocument();
            document.LoadHtml(strResponse);
            HtmlNode node = document.DocumentNode;

            objResponse.Respons = enmResponse.Success;
            //-------------------------------------------------------------------------------------------

            foreach (HtmlNode td in document.DocumentNode.SelectNodes("//table[@class='grid ']//tr//td"))
            {

                string Row1 = td.ChildNodes[1].InnerText.Trim();

                if (Row1 != "")
                {
                    string row2 = td.ChildNodes[3].InnerText.Trim().Replace("\t", "").Replace("\r\n", " ");

                    if (Row1.ToUpper() == "TAN")
                    {
                        objDetails.TAN = row2;
                    }

                    if (Row1.ToUpper() == "CATEGORY OF DEDUCTOR")
                    {
                        objDetails.DeducteeCategory = row2;
                    }
                    if (Row1.ToUpper() == "NAME")
                    {
                        objDetails.Name = row2;
                    }
                    if (Row1.ToUpper() == "ADDRESS")
                    {
                        objDetails.Address = row2;
                    }
                    if (Row1.ToUpper() == "PAN")
                    {
                        objDetails.PAN = row2;
                    }
                    if (Row1.ToUpper() == "STATUS OF TAN")
                    {
                        objDetails.StatusOfTAN = row2;
                    }
                    if (Row1.ToUpper() == "EMAIL ID 1")
                    {
                        objDetails.EmailID1 = row2;
                    }

                    if (Row1.ToUpper() == "EMAIL ID 2.")
                    {
                        objDetails.EmailID2 = row2;
                    }
                    if (Row1.ToUpper() == "AREA CODE")
                    {
                        objDetails.AreaCode = row2;
                    }
                    if (Row1.ToUpper() == "AO TYPE")
                    {
                        objDetails.AOType = row2;
                    }
                    if (Row1.ToUpper() == "RANGE CODE")
                    {
                        objDetails.RangeCode = row2;
                    }
                    if (Row1.ToUpper() == "AO NUMBER")
                    {
                        objDetails.AONumber = row2;
                    }
                    if (Row1.ToUpper() == "AO DESCRIPTION")
                    {
                        objDetails.AODescription = row2;
                    }
                    if (Row1.ToUpper() == "BUILDING NAME")
                    {
                        objDetails.BuildingName = row2;
                    }
                    if (Row1.ToUpper() == "EMAIL ID")
                    {
                        objDetails.EmailID = row2;
                    }
                }
            }
            //-----------------------------------
            objResponse.CustomeTypes = objDetails;

            return objResponse;
        }
