        #region RequestForDownloadForm16SearchPAN_New
        public TracesResponse RequestForDownloadForm16SearchPAN_New(TracesLogin objLogin, TracesData objTraceData, List<string> SearchPans)
        {
            string strResponse = "";
            StringBuilder sbParameter;
            TracesResponse objResponse = new TracesResponse();
            //-------------------------------------------------
            try
            {
                if (SearchPans.Count <= 0)
                {
                    objResponse.Message = "Please enter atleast one PAN";
                    objResponse.Respons = enmResponse.Failed;
                    this.Logoff();

                    return objResponse;
                }
                //===================================================
                /* --------------------------------------------------------------------
                1.> REQUEST FOR LOGIN INTO TRACES SITES
                    URL :: https://www.tdscpc.gov.in/app/login.xhtml
                 --------------------------------------------------------------------*/
                if (!IsSessionExists)
                {
                    objResponse = this.makeLoginToTraces_New(objLogin);
                    if (objResponse.Respons == enmResponse.Failed)
                        return objResponse;
                }

                // ================================
                // STEP 1: INIT OLD DOMAIN COOKIE
                // ================================
                //makeHTTPGetRequest(
                //    "https://traces61.tdscpc.gov.in/",
                //    "https://traces.tdscpc.gov.in/"
                //);

                // ================================
                // STEP 2: SESSION BRIDGE
                // ================================
                makeHTTPGetRequest(
                    strBaseURL + "preauthV2.xhtml",
                    "https://traces.tdscpc.gov.in/"
                );

                // ================================
                // STEP 3: OPEN PAGE
                // ================================
                makeHTTPGetRequest(
                    strBaseURL + "ded/download16.xhtml",
                    strBaseURL + "preauthV2.xhtml"
                );
                /* --------------------------------------------------------------------
                  2.> REQUEST FOR FORM 16 CERTIFICATE FILE( download16.xhtml file )
                      URL :: https://www.tdscpc.gov.in/app/ded/download16.xhtml
                   --------------------------------------------------------------------*/
                strResponse = makeHTTPGetRequest(strBaseURL + "ded/download16.xhtml");

                //CHECKING ANY ERROR FROM SERVER POINT
                if (!IsStringExists(strResponse, "//form[@id=\"searchPan\"]"))
                {
                    objResponse.Message = "Server Error";
                    objResponse.Respons = enmResponse.SessionTimeout;
                    this.Logoff();

                    return objResponse;
                }
                //------------------------------------------------------------
                //-- Validate all Pan in pan list
                //-----------------------------------------------------------
                sbParameter = new StringBuilder();
                Dictionary<string, string> objNameval = null;
                //-----------------------------------------
                List<string> objPanlst = new List<string>();
                foreach (string pan in SearchPans)
                {
                    sbParameter = new StringBuilder();
