        public TracesResponse UploadCSVPANFile(string filePath, out string tokenNo, out string uploadedFilePath)
        {
            TracesResponse resp = new TracesResponse { Respons = enmResponse.Success };

            tokenNo = "";
            uploadedFilePath = "";

            try
            {
                string url = "https://traces-app.tdscpc.gov.in/validationservice/api/pan-verify/submit";
                string boundary = "----WebKitFormBoundary" + DateTime.Now.Ticks.ToString("x");

                var request = (HttpWebRequest)WebRequest.Create(url);
                request.Method = "POST";
                request.ContentType = "multipart/form-data; boundary=" + boundary;
                request.CookieContainer = TracesSession.CookieJar;

                // IMPORTANT FIXES
                ServicePointManager.Expect100Continue = false;
                request.ServicePoint.Expect100Continue = false;
                request.KeepAlive = true;
                request.ProtocolVersion = HttpVersion.Version11;
                request.AllowWriteStreamBuffering = true;
                request.SendChunked = false;

                // HEADERS
                request.Headers["Authorization"] = "Bearer " + tracesAuthToken;
                request.Headers["Origin"] = "https://traces.tdscpc.gov.in";
                request.Referer = "https://traces.tdscpc.gov.in/";
                request.Accept = "*/*";
                request.UserAgent = "Mozilla/5.0";

                // BUILD FULL BODY IN MEMORY
                byte[] bodyBytes;

                using (var ms = new MemoryStream())
                {
                    using (var writer = new StreamWriter(ms, new UTF8Encoding(false)))
                    {
                        // FIELD 1: userId
                        writer.Write("--" + boundary + "\r\n");
                        writer.Write("Content-Disposition: form-data; name=\"userId\"\r\n\r\n");
                        writer.Write(TracesSession.TAN + "\r\n");

                        // FIELD 2: file
                        writer.Write("--" + boundary + "\r\n");
                        //writer.Write("Content-Disposition: form-data; name=\"file\"; filename=\"" + Path.GetFileName(filePath) + "\"\r\n");
                        //writer.Write("Content-Type: text/csv\r\n\r\n");
                        writer.Write("Content-Type: text/csv\r\n");
                        writer.Write("Content-Disposition: form-data; name=\"file\"; filename=\"" + Path.GetFileName(filePath) + "\"\r\n\r\n");
                        writer.Flush();

                        // WRITE FILE BYTES
                        byte[] fileBytes = File.ReadAllBytes(filePath);
                        ms.Write(fileBytes, 0, fileBytes.Length);

                        writer.Write("\r\n");
                        writer.Write("--" + boundary + "--\r\n");
                        writer.Flush();
                    }

                    bodyBytes = ms.ToArray();
                }

                // SET CONTENT LENGTH (CRITICAL)
                request.ContentLength = bodyBytes.Length;

                using (var reqStream = request.GetRequestStream())
                {
                    reqStream.Write(bodyBytes, 0, bodyBytes.Length);
                }

                // RESPONSE
                string responseText = "";

                using (var response = (HttpWebResponse)request.GetResponse())
                using (var reader = new StreamReader(response.GetResponseStream()))
                {
                    responseText = reader.ReadToEnd();
                }

                // PARSE RESPONSE
                dynamic obj = Newtonsoft.Json.JsonConvert.DeserializeObject(responseText);

                tokenNo = obj?.data?.tokenNo ?? "";
                uploadedFilePath = obj?.data?.filePath ?? "";

                if (!string.IsNullOrEmpty(tokenNo))
                {
                    resp.Respons = enmResponse.Success;
                    resp.Message = "Uploaded successfully. Token: " + tokenNo;
                }
                else
                {
                    resp.Respons = enmResponse.Failed;
                    resp.Message = "Token not found. Response: " + responseText;
                }

                return resp;
            }
            catch (WebException ex)
            {
                string err = "";

                if (ex.Response != null)
                {
                    using (var reader = new StreamReader(ex.Response.GetResponseStream()))
                    {
                        err = reader.ReadToEnd();
                    }
                }

                resp.Respons = enmResponse.Failed;
                resp.Message = "Upload Error: " + err;
                return resp;
            }
        }
        #endregion

