        public TracesResponse DownloadCSVPANResult1(string tokenNo, string saveFolder)
        {
            TracesResponse resp = new TracesResponse();

            try
            {
                string url = "https://traces-app.tdscpc.gov.in/validationservice/api/pan-verify/download-by-token?tokenNo=" + tokenNo;

                ServicePointManager.Expect100Continue = false;
                ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;

                var request = (HttpWebRequest)WebRequest.Create(url);
                request.Method = "GET";
                request.CookieContainer = TracesSession.CookieJar;

                request.Headers["Authorization"] = "Bearer " + tracesAuthToken;
                request.Headers["Origin"] = "https://traces.tdscpc.gov.in";
                request.Referer = "https://traces.tdscpc.gov.in/";
                request.Accept = "*/*";
                request.UserAgent = "Mozilla/5.0";

                request.KeepAlive = true;
                request.ProtocolVersion = HttpVersion.Version11;
                request.AutomaticDecompression = DecompressionMethods.GZip | DecompressionMethods.Deflate;

                using (var response = (HttpWebResponse)request.GetResponse())
                {
                    // GET ACTUAL FILE NAME
                    string fileName = "PAN_Data_" + tokenNo + ".csv";

                    string disposition = response.Headers["Content-Disposition"];
                    if (!string.IsNullOrEmpty(disposition))
                    {
                        var match = System.Text.RegularExpressions.Regex.Match(disposition, "filename=(.+)");
                        if (match.Success)
                        {
                            fileName = match.Groups[1].Value.Trim('"');
                        }
                    }

                    string fullPath = Path.Combine(saveFolder, fileName);

                    using (var stream = response.GetResponseStream())
                    using (var fs = new FileStream(fullPath, FileMode.Create, FileAccess.Write))
                    {
                        stream.CopyTo(fs);
                    }

                    resp.Respons = enmResponse.Success;
                    resp.Message = "Downloaded: " + fileName;
                    return resp;
                }
            }
            catch (WebException ex)
            {
                string err = "";

                if (ex.Response != null)
                {
                    using (var reader = new StreamReader(ex.Response.GetResponseStream()))
                    {
                        err = reader.ReadToEnd();
                    }
                }

                resp.Respons = enmResponse.Failed;
                resp.Message = "Download Error: " + err;
                return resp;
            }
        }

        public TracesResponse DownloadCSVPANResult(
                            string tokenNo,
                            string saveFolder)
        {
            TracesResponse resp = new TracesResponse();

            int retryCount = 3;

            for (int attempt = 1; attempt <= retryCount; attempt++)
            {
                try
                {
                    string url =
                        "https://traces-app.tdscpc.gov.in/validationservice/api/pan-verify/download-by-token?tokenNo="
                        + tokenNo;

                    ServicePointManager.Expect100Continue = false;
                    ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;

                    var request =
                        (HttpWebRequest)WebRequest.Create(url);

                    request.Method = "GET";
                    request.CookieContainer = TracesSession.CookieJar;

                    request.Headers["Authorization"] =
                        "Bearer " + tracesAuthToken;

                    request.Headers["Origin"] =
                        "https://traces.tdscpc.gov.in";

                    request.Referer =
                        "https://traces.tdscpc.gov.in/";

                    request.Accept = "*/*";
                    request.UserAgent = "Mozilla/5.0";

                    request.KeepAlive = true;
                    request.ProtocolVersion = HttpVersion.Version11;

                    request.AutomaticDecompression =
                        DecompressionMethods.GZip |
                        DecompressionMethods.Deflate;

                    using (var response =
                        (HttpWebResponse)request.GetResponse())
                    {
                        string fileName =
                            "PAN_Data_" + tokenNo + ".csv";

                        string disposition =
                            response.Headers["Content-Disposition"];

                        if (!string.IsNullOrEmpty(disposition))
                        {
                            var match =
                                System.Text.RegularExpressions.Regex.Match(
                                    disposition,
                                    "filename=(.+)");

                            if (match.Success)
                            {
                                fileName =
                                    match.Groups[1]
                                    .Value
                                    .Trim('"');
                            }
                        }

                        string fullPath =
                            Path.Combine(saveFolder, fileName);

                        using (var stream =
                            response.GetResponseStream())
                        using (var fs =
                            new FileStream(
                                fullPath,
                                FileMode.Create,
                                FileAccess.Write))
                        {
                            stream.CopyTo(fs);
                        }

                        resp.Respons = enmResponse.Success;
                        resp.Message = fullPath;

                        return resp;
                    }
                }
                catch (WebException ex)
                {
                    //-------------------------------------------------
                    // RETRY ONLY FOR 500 ERROR
                    //-------------------------------------------------
                    HttpWebResponse webResp =
                        ex.Response as HttpWebResponse;

                    if (webResp != null &&
                        webResp.StatusCode ==
                        HttpStatusCode.InternalServerError)
                    {
                        //-------------------------------------------------
                        // WAIT 2 SEC AND RETRY
                        //-------------------------------------------------
                        System.Threading.Thread.Sleep(2000);

                        continue;
                    }

                    string err = "";

                    if (ex.Response != null)
                    {
                        using (var reader =
                            new StreamReader(
                                ex.Response.GetResponseStream()))
                        {
                            err = reader.ReadToEnd();
                        }
                    }

                    resp.Respons = enmResponse.Failed;
                    resp.Message = "Download Error: " + err;

                    return resp;
                }
            }

            //-------------------------------------------------
            // ALL RETRIES FAILED
            //-------------------------------------------------
            resp.Respons = enmResponse.Failed;

            resp.Message =
                "TRACES server is still processing the CSV. " +
                "Please try again after some time.";

            return resp;
        }
        #endregion

        #region GetPANVerificationTokens
        public DataTable GetPANVerificationTokens(int topRecords = 3)
        {
            DataTable dt = new DataTable();

            dt.Columns.Add("TOKENNO");
            dt.Columns.Add("STATUS");
            dt.Columns.Add("SUBMITTEDDATE");

            try
            {
                string url =
                    "https://traces-app.tdscpc.gov.in/validationservice/api/pan-verify/filter?" +
                    "userId=" + TracesSession.TAN +
                    "&tokenNo=" +
                    "&page=0" +
                    "&size=10" +
                    "&fromDate=" +
                    "&toDate=" +
                    "&status=";

                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);

                request.Method = "GET";
                request.CookieContainer = TracesSession.CookieJar;

                request.Headers["Authorization"] = "Bearer " + tracesAuthToken;
                request.Headers["Origin"] = "https://traces.tdscpc.gov.in";
                request.Referer = "https://traces.tdscpc.gov.in/";

                request.Accept = "*/*";
                request.UserAgent = "Mozilla/5.0";

                request.KeepAlive = true;
                request.ProtocolVersion = HttpVersion.Version11;

                string responseText = "";

                using (HttpWebResponse response =
                    (HttpWebResponse)request.GetResponse())
                {
                    using (StreamReader reader =
                        new StreamReader(response.GetResponseStream()))
                    {
                        responseText = reader.ReadToEnd();
                    }
                }

                dynamic obj =
                    Newtonsoft.Json.JsonConvert.DeserializeObject(responseText);

                int addedCount = 0;

                foreach (var item in obj.data.content)
                {
                    string tokenNo =
                        Convert.ToString(item.tokenNo);

                    string submittedDate = "";

                    try
                    {
                        submittedDate =
                            Convert.ToDateTime(item.subDate.ToString())
                            .ToString("dd/MM/yyyy");
                    }
                    catch
                    {
                    }

                    //-------------------------------------------------
                    // FETCH LAST STATUS FROM ARRAY
                    //-------------------------------------------------
                    string finalStatus = "";

                    try
                    {
                        if (item.status != null)
                        {
                            int cnt = item.status.Count;

                            if (cnt > 0)
                            {
                                finalStatus =
                                    Convert.ToString(item.status[cnt - 1]);
                            }
                        }
                    }
                    catch
                    {
                    }

                    //-------------------------------------------------
                    // ONLY AVAILABLE TOKENS
                    //-------------------------------------------------
                    if (finalStatus.ToUpper().Contains("AVAILABLE"))
                    {
                        dt.Rows.Add(
                            tokenNo,
                            finalStatus,
                            submittedDate);

                        addedCount++;

                        //-------------------------------------------------
                        // FETCH ONLY TOP 3
                        //-------------------------------------------------
                        if (addedCount >= topRecords)
                            break;
                    }
                }
            }
            catch (Exception ex)
            {
            }

            return dt;
        }
        #endregion

        #region CheckPANVerificationTokenStatus
        public string CheckPANVerificationTokenStatus(string tokenNo)
        {
            try
            {
                string url =
                    "https://traces-app.tdscpc.gov.in/validationservice/api/pan-verify/filter?" +
                    "userId=" + TracesSession.TAN +
                    "&tokenNo=" + tokenNo +
                    "&page=0" +
                    "&size=10" +
                    "&fromDate=" +
                    "&toDate=" +
                    "&status=";

                HttpWebRequest request =
                    (HttpWebRequest)WebRequest.Create(url);

                request.Method = "GET";

                request.CookieContainer = TracesSession.CookieJar;

                request.Headers["Authorization"] =
                    "Bearer " + tracesAuthToken;

                request.Headers["Origin"] =
                    "https://traces.tdscpc.gov.in";

                request.Referer =
                    "https://traces.tdscpc.gov.in/";

                request.Accept = "*/*";
                request.UserAgent = "Mozilla/5.0";

                request.KeepAlive = true;
                request.ProtocolVersion = HttpVersion.Version11;

                string responseText = "";

                using (HttpWebResponse response =
                    (HttpWebResponse)request.GetResponse())
                {
                    using (StreamReader reader =
                        new StreamReader(response.GetResponseStream()))
                    {
                        responseText = reader.ReadToEnd();
                    }
                }

                dynamic obj =
                    Newtonsoft.Json.JsonConvert.DeserializeObject(responseText);

                //-------------------------------------------------
                // CHECK CONTENT EXISTS
                //-------------------------------------------------
                if (obj == null ||
                    obj.data == null ||
                    obj.data.content == null ||
                    obj.data.content.Count == 0)
                {
                    return "NOTFOUND";
                }

                //-------------------------------------------------
                // FIRST RECORD
                //-------------------------------------------------
                var item = obj.data.content[0];

                //-------------------------------------------------
                // FETCH LAST STATUS
                //-------------------------------------------------
                string finalStatus = "";

                try
                {
                    if (item.status != null)
                    {
                        int cnt = item.status.Count;

                        if (cnt > 0)
                        {
                            finalStatus =
                                Convert.ToString(item.status[cnt - 1]);
                        }
                    }
                }
                catch
                {
                }

                //-------------------------------------------------
                // RETURN FINAL STATUS
                //-------------------------------------------------
                if (finalStatus.ToUpper().Contains("AVAILABLE"))
                    return "AVAILABLE";

                if (finalStatus.ToUpper().Contains("PENDING"))
                    return "PENDING";

                if (finalStatus.ToUpper().Contains("FAILED"))
                    return "FAILED";

                return finalStatus.ToUpper();
            }
            catch (Exception ex)
            {
                return "ERROR";
            }
        }
        #endregion

        #region IsPANFileReady
        public bool IsPANFileReady(string tokenNo)
        {
            try
            {
                string url =
                    "https://traces-app.tdscpc.gov.in/validationservice/api/pan-verify/filter" +
                    "?userId=" + TracesSession.TAN +
                    "&tokenNo=" + tokenNo +
                    "&page=0" +
                    "&size=10" +
                    "&fromDate=" +
                    "&toDate=" +
                    "&status=ALL";

                ServicePointManager.Expect100Continue = false;
                ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;

                var request = (HttpWebRequest)WebRequest.Create(url);

                request.Method = "GET";
                request.CookieContainer = TracesSession.CookieJar;

                request.Headers["Authorization"] = "Bearer " + tracesAuthToken;
                request.Headers["Origin"] = "https://traces.tdscpc.gov.in";
                request.Referer = "https://traces.tdscpc.gov.in/";
                request.Accept = "application/json, text/plain, */*";
                request.UserAgent = "Mozilla/5.0";

                request.KeepAlive = true;
                request.ProtocolVersion = HttpVersion.Version11;

                string responseText = "";

                using (var response = (HttpWebResponse)request.GetResponse())
                using (var reader = new StreamReader(response.GetResponseStream()))
                {
                    responseText = reader.ReadToEnd();
                }

                // DEBUG
                // MessageBox.Show(responseText);

                string upper = responseText.ToUpper();

                // AVAILABLE
                if (upper.Contains("AVAILABLE"))
                {
                    return true;
                }

                // PENDING
                if (upper.Contains("PENDING"))
                {
                    return false;
                }

                return false;
            }
            catch
            {
                return false;
            }
        }
