        private string PostJsonRequest(string url, string jsonPayload, string referer = "")
        {
            ServicePointManager.Expect100Continue = false;
            ServicePointManager.SecurityProtocol = (SecurityProtocolType)768 | (SecurityProtocolType)3072;
            ServicePointManager.ServerCertificateValidationCallback =
                new RemoteCertificateValidationCallback(delegate { return true; });

            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
            request.Method = "POST";
            request.KeepAlive = true;
            request.Accept = "application/json, text/plain, */*";
            request.ContentType = "application/json;charset=UTF-8";
            request.UserAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120 Safari/537.36";

            if (!string.IsNullOrEmpty(referer))
                request.Referer = referer;

            request.Headers.Add("Origin", "https://traces.tdscpc.gov.in");
            request.Headers.Add("Accept-Language", "en-US,en;q=0.9");
            request.Headers.Add("X-Requested-With", "XMLHttpRequest");

            request.CookieContainer = objContainer;

            if (!string.IsNullOrEmpty(tracesAuthToken))
                request.Headers.Add("Authorization", "Bearer " + tracesAuthToken);

            byte[] data = Encoding.UTF8.GetBytes(jsonPayload);
            request.ContentLength = data.Length;

            using (var stream = request.GetRequestStream())
                stream.Write(data, 0, data.Length);

            using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
            {
                objContainer.Add(response.Cookies);

                using (var reader = new StreamReader(response.GetResponseStream()))
                    return reader.ReadToEnd();
            }
        }

        //private string FormatTracesApiDate(DateTime dt)
        //{
        //    return dt.Day.ToString() + "-" + dt.ToString("MM-yyyy");
        //}
        private string FormatTracesApiDate(string inputDate)
        {
            DateTime dt = dtService.J_ConvertddMMyyyy(inputDate);
            return dt.Day.ToString() + "-" + dt.ToString("MM-yyyy", System.Globalization.CultureInfo.InvariantCulture);
        }

        private string MapMatchStatus(string oldStatus)
        {
            if (string.IsNullOrWhiteSpace(oldStatus))
                return "UNCLAIMED";

            oldStatus = oldStatus.Trim().ToUpper();

            switch (oldStatus)
            {
                case "U":
                case "UNCLAIMED":
                    return "UNCLAIMED";

                case "C":
                case "CLAIMED":
                    return "CLAIMED";

                case "A":
                case "ALL":
                default:
                    return "UNCLAIMED";   // temporary for first working run
            }
        }

        #region CIN_Period_Payment_API
        public TracesResponse CIN_Period_Payment_API(TracesData objData)
        {
            TracesResponse objResponse = new TracesResponse();
            objResponse.Respons = enmResponse.Success;

            try
            {
                DataTable table = CreateChallanTable();

                // 1. CLAIMED challans
                FetchChallanStatusAndFillTable(
                    objData,
                    "CLAIMED",
                    true,
                    table
                );

                // 2. UNCLAIMED challans
                FetchChallanStatusAndFillTable(
                    objData,
                    "UNCLAIMED",
                    false,
                    table
                );

                objResponse.CustomeTypes = table;
            }
            catch (WebException ex)
            {
                string err = "";
                if (ex.Response != null)
                {
                    using (var reader = new StreamReader(ex.Response.GetResponseStream()))
                        err = reader.ReadToEnd();
                }

                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = string.IsNullOrEmpty(err) ? ex.Message : err;
            }
            catch (Exception ex)
            {
                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = ex.Message;
            }

            return objResponse;
        }

        private void FetchChallanStatusAndFillTable(
                                            TracesData objData,
                                            string matchStatus,
                                            bool includeConsumptionStatus,
                                            DataTable table)
        {
            var payload = new TracesChallanVerifyRequest
            {
                tan = TracesSession.TAN,
                fromDate = FormatTracesApiDate(objData.FromChallanDepositDate),
                toDate = FormatTracesApiDate(objData.ToChallanDepositDate),
                matchStatus = matchStatus
            };

            if (includeConsumptionStatus)
            {
                payload.consumptionStatus = new List<string>
        {
            "PARTIALLY CONSUMED",
            "FULLY CONSUMED"
        };
            }
            else
            {
                payload.consumptionStatus = null;
            }

            string url = "https://traces-app.tdscpc.gov.in/oltaschallancorrection/deductor/challan/searchPeriodOfPayment?page=0&size=2000";
            ////string url = "https://traces-app.tdscpc.gov.in/oltaschallancorrection/deductor/bin/periodOfpayment?page=0&size=2000";

            string json = JsonConvert.SerializeObject(
                payload,
                new JsonSerializerSettings
                {
                    NullValueHandling = NullValueHandling.Ignore
                });

            string responseText = PostJsonRequest(
                url,
                json,
                "https://traces.tdscpc.gov.in/auth/CheckChallanStatus/Deductor"
            );

            var apiResp = JsonConvert.DeserializeObject<TracesChallanVerifyResponse>(responseText);

            if (apiResp != null && apiResp.data != null)
            {
                foreach (var item in apiResp.data)
                {
                    AddChallanRow(table, item);
                }
            }
        }

        private DataTable CreateChallanTable()
        {
            DataTable table = new DataTable();

            table.Columns.Add("Bank Code");
            table.Columns.Add("Branch Code");
            table.Columns.Add("Date of Deposit");
            table.Columns.Add("Challan Serial Number");
            table.Columns.Add("Challan Status");
            table.Columns.Add("Recipt Number");
            table.Columns.Add("Challan Amount");

            return table;
        }

        private void AddChallanRow(DataTable table, TracesChallanItem item)
        {
            DataRow dRow = table.NewRow();

            string bsr = item.bsrCode ?? "";
            string bankCode = "";
            string branchCode = "";

            if (bsr.Length >= 7)
            {
                bankCode = bsr.Substring(0, 3);
                branchCode = bsr.Substring(3);
            }
            else
            {
                branchCode = bsr;
            }

            dRow["Bank Code"] = bankCode;
            dRow["Branch Code"] = branchCode;
            dRow["Date of Deposit"] = item.challanDepositDate;
            dRow["Challan Serial Number"] = Convert.ToString(item.challanSeqNum);
            dRow["Challan Status"] = item.matchStatus;
            dRow["Recipt Number"] = Convert.ToString(item.receiptNum);
            dRow["Challan Amount"] = string.Format("{0:0.00}", item.totalAmount);

            table.Rows.Add(dRow);
        }
        #endregion

