                        err = reader.ReadToEnd();
                }

                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = string.IsNullOrEmpty(err) ? ex.Message : err;
            }
            catch (Exception ex)
            {
                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = ex.Message;
            }

            return objResponse;
        }

        private DataTable CreateBINChallanTable()
        {
            DataTable table = new DataTable();

            table.Columns.Add("Bank Code");
            table.Columns.Add("Branch Code");
            table.Columns.Add("Date of Deposit");
            table.Columns.Add("Challan Serial Number");
            table.Columns.Add("Challan Status");
            table.Columns.Add("Recipt Number");
            table.Columns.Add("Challan Amount");

            return table;
        }

        private void AddBINChallanRow(DataTable table, TracesBINChallanItem item)
        {
            DataRow dRow = table.NewRow();

            string receiptNo = item.receiptNumber ?? "";
            string bankCode = "";
            string branchCode = "";

            if (receiptNo.Length >= 7)
            {
                bankCode = receiptNo.Substring(0, 3);
                branchCode = receiptNo.Substring(3);
            }
            else
            {
                branchCode = receiptNo;
            }

            dRow["Bank Code"] = bankCode;
            dRow["Branch Code"] = branchCode;
            dRow["Date of Deposit"] = item.tvDate;
            dRow["Challan Serial Number"] = Convert.ToString(item.ddoSerialNumber);
            dRow["Challan Status"] = item.matchStatus;
            dRow["Recipt Number"] = item.receiptNumber;
            dRow["Challan Amount"] = string.Format("{0:0.00}", item.tvAmount);

            table.Rows.Add(dRow);
        }
        #endregion

        #region CIN_GetChallan
        public TracesResponse CIN_GetChallan(TracesData objData)
        {
            TracesResponse objResponse = new TracesResponse();
            objResponse.Respons = enmResponse.Success;

            DataTable table = new DataTable();

            try
            {
                //table.Columns.Add("Bank Code");
                //table.Columns.Add("Branch Code");
                //table.Columns.Add("Date of Deposit");
                //table.Columns.Add("Challan Serial Number");
                //table.Columns.Add("Challan Status");
                //table.Columns.Add("Recipt Number");
                //table.Columns.Add("Challan Amount");
                table = CreateCINGetChallanTable();
                // Fetch CLAIMED challans
                FetchCINPeriodPaymentAndFillTable(objData, "CLAIMED", true, table);

                // Fetch UNCLAIMED challans
                FetchCINPeriodPaymentAndFillTable(objData, "UNCLAIMED", false, table);

                objResponse.CustomeTypes = table;
            }
            catch (Exception err)
            {
                objResponse.Respons = enmResponse.Failed;
                objResponse.Message = err.Message;
            }

            return objResponse;
        }
        //
        #region FetchCINPeriodPaymentAndFillTable
        private void FetchCINPeriodPaymentAndFillTable(
            TracesData objData,
            string matchStatus,
            bool includeConsumptionStatus,
            DataTable table)
        {
            var payload = new TracesChallanVerifyRequest
            {
                tan = TracesSession.TAN,
                fromDate = FormatTracesApiDate(objData.FromChallanDepositDate),
                toDate = FormatTracesApiDate(objData.ToChallanDepositDate),
                matchStatus = matchStatus
            };

            if (includeConsumptionStatus)
            {
                payload.consumptionStatus = new List<string>
        {
            "PARTIALLY CONSUMED",
            "FULLY CONSUMED"
        };
            }
            else
            {
                payload.consumptionStatus = null;
            }

            string url =
                "https://traces-app.tdscpc.gov.in/oltaschallancorrection/deductor/challan/searchPeriodOfPayment?page=0&size=2000";

            string json = JsonConvert.SerializeObject(
                payload,
                new JsonSerializerSettings
                {
                    NullValueHandling = NullValueHandling.Ignore
                });

            string responseText = PostJsonRequest(
                url,
                json,
                "https://traces.tdscpc.gov.in/auth/CheckChallanStatus/Deductor"
            );

            var apiResp =
                JsonConvert.DeserializeObject<TracesChallanVerifyResponse>(responseText);

            if (apiResp != null && apiResp.data != null)
            {
                foreach (var item in apiResp.data)
                {
                    AddCINGetChallanRow(table, item);
                }
            }
        }
        #endregion

        public class TracesChallanVerifyRequest
        {
            public string tan { get; set; }
            public string fromDate { get; set; }
            public string toDate { get; set; }
            public string matchStatus { get; set; }
            public List<string> consumptionStatus { get; set; }
        }
        private DataTable CreateCINGetChallanTable()
        {
            DataTable table = new DataTable();

            table.Columns.Add("Bank Code");
            table.Columns.Add("Branch Code");
            table.Columns.Add("Date of Deposit");
            table.Columns.Add("Challan Serial Number");
            table.Columns.Add("Challan Status");
            table.Columns.Add("Challan Amount");

            return table;
        }

        private void AddCINGetChallanRow(DataTable table, TracesChallanItem item)
        {
            DataRow dRow = table.NewRow();

            string bsr = item.bsrCode ?? "";
            string bankCode = "";
            string branchCode = "";

            if (bsr.Length >= 7)
            {
                bankCode = bsr.Substring(0, 3);
                branchCode = bsr.Substring(3);
            }
            else
            {
                branchCode = bsr;
            }

            dRow["Bank Code"] = bankCode;
            dRow["Branch Code"] = branchCode;
            dRow["Date of Deposit"] = item.challanDepositDate;
            dRow["Challan Serial Number"] = Convert.ToString(item.challanSeqNum);
            dRow["Challan Status"] = item.matchStatus;
            dRow["Challan Amount"] = string.Format("{0:0.00}", item.totalAmount);

            table.Rows.Add(dRow);
        }

        #endregion
        
               
        #region makeHTTPGetRequest_NewITAct

        private string makeHTTPGetRequest_NewITAct(string strURL)
        {
            request = (HttpWebRequest)WebRequest.Create(strURL);

            request.Method = "GET";
            request.KeepAlive = true;

            request.UserAgent =
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/138.0 Safari/537.36";

            request.Accept = "application/json, text/plain, */*";

            request.ContentType = "application/json";

            request.Timeout = 1000000000;

            if (request.CookieContainer == null)
                request.CookieContainer = objContainer;

            response = (HttpWebResponse)request.GetResponse();

            request.CookieContainer.Add(response.Cookies);

            dataStream = response.GetResponseStream();

            reader = new StreamReader(dataStream);

            strServerResponse = reader.ReadToEnd();

            reader.Close();
            dataStream.Close();
            response.Close();

            return strServerResponse;
        }

        #endregion

        #region makeHTTPPostJSONRequest_NewITAct

        private string makeHTTPPostJSONRequest_NewITAct(string strURL, string strJSON)
        {
            request = (HttpWebRequest)WebRequest.Create(strURL);

            request.Method = "POST";
            request.KeepAlive = true;

            request.UserAgent =
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/138.0 Safari/537.36";

            request.Accept = "application/json, text/plain, */*";

            request.ContentType = "application/json";

            request.Timeout = 1000000000;

            if (request.CookieContainer == null)
                request.CookieContainer = objContainer;

            byte[] buffer = Encoding.UTF8.GetBytes(strJSON);

            request.ContentLength = buffer.Length;

            using (Stream stream = request.GetRequestStream())
            {
                stream.Write(buffer, 0, buffer.Length);
            }

            response = (HttpWebResponse)request.GetResponse();

            request.CookieContainer.Add(response.Cookies);

            dataStream = response.GetResponseStream();

            reader = new StreamReader(dataStream);

            strServerResponse = reader.ReadToEnd();

            reader.Close();
            dataStream.Close();
            response.Close();

            return strServerResponse;
        }

        #endregion


